INSERT INTO `articles` (`id`, `title`, `slug`, `content`, `category_id`, `image`, `user_id`, `editable`, `user_id_last_edit`, `meta_description`, `meta_author`, `meta_keyword`, `og_image`, `og_title`, `og_description`, `featured`, `status`, `read_count`, `active`, `date`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1,	'Ujian Sertifikasi Kompetensi Di bidang Jaringan Komputer',	'ujian-sertifikasi-kompetensi-di-bidang-jaringan-komputer',	'<p>Uji Kompetensi merupakan suatu instrumen yang di wajibkan pemerintah untuk memastikan kualitas lulusan tenaga IT itu berkualitas atau tidak. Kegiatan ini dilaksanakan pada tanggal 22 s.d. 23 Desember 2016 di Lab Arsitektur dan Jaringan Komputer di Jurusan Teknologi Informasi.</p>\n<p>JTI POLIJE sebagai salah satu lembaga pendidikan tinggi juga mempunyai kwajiban untuk menyediakan tenaga IT yang profesional, salah satunya adalah dengan mengadakan uji kompetensi mahasiswa.</p>\n<p>Tujuan awalnya sangat baik selain sebagai peningkatan akses terhadap dunia IT, juga sebagai tolak ukur keberhasilan pembelajaran yang dilalui oleh mahasiswa.</p>\n<p>Dalam uji kompetensi terdapat suatu proses untuk mengukur pengetahuan, keterampilan, dan sikap tenaga IT sesuai dengan standar profesi, diharapkan dengan adanya uji kompetensi ini selain mendapatkan ijazah mahasiswa JTI POLIJE Juga mampu bersaing secara global dengan ditunjukkannya sertifkat pendamping ijazah.</p>\n<p> </p>',	6,	'uji.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	'uji.jpg',	NULL,	NULL,	1,	1,	8265,	1,	'2017-04-12 15:12:48',	'2017-04-12 15:12:48',	'2026-11-24 22:12:40',	NULL),
(3,	'Kegiatan Praktek Lapang Manajemen Informatika Ke Diskominfo dan RADNET Surabaya',	'kegiatan-praktek-lapang-manajemen-informatika-ke-diskominfo-dan-radnet-surabaya',	'<p>Guna pencapaian Tujuan Instruksional Umum (ITU) dan Tujuan Instruksional Khusus (TIK) pada mata kuliah Manajemen Basis Data dan Sistem Informasi Geografis, Jurusan Manajemen Informatika Semester 4 Politeknik Negeri Jember mengunjungi Diskominfo Jatim dan RADNET Surabaya pada Selasa (25/4) siang.</p>\n<p> </p>\n<p>Untuk mendapatkan informasi lebih banyak dan efisiensi waktu, Mahasiswa dibagi menjadi dua kelompok yaitu 30 orang berkunjung ke Data Center Pemprov Jatim dan sebagian besar sisanya pergi ke Data Center RADNET Surabaya.</p>\n<p> </p>\n<p>Ketua Program Studi Manajemen Informatika Politeknik Negeri Jember, Dwi Putro Sarwo, S.Kom, M.Kom, menyampaikan kunjungan tersebut untuk mengetahui alur proses, tahapan pengembangan dan pengelolaan basis data pada ruang Data Center Pemprov Jatim dan RADNET Surabaya. \"Ini sangat penting kami lakukan karena demi mengembangkan program mata kuliah,\" kata P. Dwi.</p>\n<p> </p>\n<p>Sementara di Diskominfo jatim Kepala Bidang Infrastruktur TIK, Hagung Sipri, menjelaskan bahwa Diskominfo Jatim menyediakan kebutuhan  bandwidth dan Intranet bagi Organisai Perangkat Daaerah (OPD). Dalam hal ini termasuk jaminan konektifitas, ketersediaan dan pemeliharaan sepenuhnya menjadi tanggung jawa Diskominfo. Dalam Pertemuan juga dijelaskan tentang perkembangan penggunaan bandwidth, dan kondisi jaringan bandwidth yang akan datang.</p>\n<p> </p>\n<p>Setelah melakukan pertemuan mahasiswa diperkenankan mengunjungi ruang Data Center dan Office tempat untuk mengetahui kegiatan sehari-hari pegawai Diskominfo Jatim dan RADNET Surabaya dalam bekerja. (dja)</p>\n<p> </p>\n<p><strong><a title=\"Kegiatan Praktek Lapang Manajemen Informatika Ke Diskominfo dan RADNET Surabaya\" href=\"http://jti.polije.ac.id/galeri/5-praktek-lapang-manajemen-informatika-ke-diskominfo-jatim-dan-radnet-surabaya\" target=\"_blank\">Lihat Galeri</a></strong></p>',	9,	'Kominfo1.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	'Kominfo1.jpg',	NULL,	NULL,	1,	1,	4426,	1,	'2017-04-27 12:06:41',	'2017-04-27 12:06:41',	'2026-11-24 18:54:37',	NULL),
(4,	'[VIDEO] Semangat Supporter IR-64 Menuju Lomba Robot',	'video-semangat-supporter-ir-64-menuju-lomba-robot',	'<p>Persiapan dilakukan oleh para supporter sebelum berangkat demi mendukung secara penuh dalam lomba robot yang diselenggarakan di Universitas Brawijaya pada 4 April 2016.</p>\n<p>Semoga tim robot IR-64 Polije mendapatkat kemenangan bisa menyapu bersih gelar juara kategori yang dilombakan!</p>\n<p>IR-64 JAYA!!! JAYA!!! JAYA!!! JUARA!!!</p>\n<p><iframe src=\"//www.youtube.com/embed/5Jv0JIeGhbA\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe></p>',	13,	'Supporter_IR-64_Polije.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	'Supporter_IR-64_Polije.jpg',	NULL,	NULL,	1,	1,	4772,	1,	'2017-05-04 10:19:59',	'2017-05-04 10:19:59',	'2026-11-24 15:00:43',	NULL),
(5,	'Direktur Memberikan Arahan Sebelum Tim Robot IR-64 Menuju Perlombaan',	'direktur-memberikan-arahan-sebelum-tim-robot-ir-64-menuju-perlombaan',	'<p>Dalam persiapan tim robot IR-64 menuju perlombaan di Universitas Brawijaya pada tanggal 4 Mei 2017, Direktur Dr. Ir. Nanang Dwi Wahyono, MM menyempatkan diri berkunjung ke gedung jurusan Teknologi Informasi didampingin Wakil Direktur Bidang Kemahasiswaan 3 Munih Dian, S.Kom, MT dan juga ketua jurusan Wahyu Kurnia D, S.Kom, MT.</p>\n<p> </p>\n<p>Dr. Ir. Nanang menyampaikan beberapa arahan dan pesan semangat kepada segenap anggota tim IR-64 yang akan berangkat ke medan perlombaan robot tersebut. kepada tim Dr. Ir. Nanang juga menyampaikan \"Kita berangkat harus membawa semangat juara, kita harus memenangkan juara 1 pada lomba robot kali ini\", pungkasnya.</p>\n<p> </p>\n<p>Akhir kata, tim IR-64 memberikan sebuah cinderamata secara simbolis kepada Direktur sebagai tanda kami siap untuk bertanding pada perlombaan robot kali ini. (dja)</p>\n<p> </p>\n<p><strong><a title=\" Pesan Semangat Direktur kepada Tim Robot IR-64\" href=\"http://jti.polije.ac.id/galeri/6-pesan-semangat-direktur-kepada-tim-robot-ir-64\" target=\"_blank\">Lihat Gallery</a></strong></p>',	13,	'P_20170504_101130.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	4377,	1,	'2017-05-04 10:49:29',	'2017-05-04 10:49:29',	'2026-11-24 16:22:21',	NULL),
(7,	'Yuk! mengenal Lebih Jauh Profil Ketua Jurusan Teknologi Informasi',	'yuk-mengenal-lebih-jauh-profil-ketua-jurusan-teknologi-informasi',	'<p><strong>Jember</strong> - Wahyu Kurnia Dewanto, S.Kom. MT, Lahir di Banyuwangi 46 tahun silam tepatnya pada 8 April 1971, beliau pada tahun 2013 telah menyelesaikan studi S2 di Universitas Brawijaya Fakultas Teknik Elektro.<br><br>Pada usia 19 tahun beliau pindah ke Malang untuk melanjutkan studi dan tinggal disana sekitar delapan tahun, kemudian beliau merantau mencari keberuntungan di ibu kota Jakarta tepatnya di Cileungsi, Bogor. Selama kurang lebih dua tahun beliau berada di Jakarta.<br><br>Kurang bersahabatnya kehidupan Jakarta, beliau kembali lagi ke Malang selama dua tahun hingga sekitar umur 30 tahun beliau menetap di Kabupaten Jember setelah beliau bekerja di Politeknik Negeri Jember hingga sekarang.<br><br>Beliau yg memiliki hobby sebelumnya yaitu nonton film dan mendengarkan live musik di kafe hingga bekerluarga hobbynya berubah menjadi internetan seperti juga nonton film streaming, main game sederhana, atau hanya sekedar mencari informasi, tetapi beliau kurang aktif di media sosial cuma hanya sekedar mengamati perkembangan teknologi dan informasi. Beliau suka makanan yang pedas-pedas. Sambil tertawa beliau mengatakan Meskipun tidak bisa bermain bola hanya menonton pertandingan di televisi beliau juga memfavoritkan salah satu klub sepak bola Liga Inggris yaitu Liverpool, meskipun sekarang di klasemen klub tersebut terseok-seok, tetapi tetap mendukung klub bola \"You&singlequote;ll Never Walk Alone\".<br><br>Pengalaman bekerja, beliau pernah bekerja sebagai sales sekitar seminggu, sempat juga menjadi supir angkot meskipun itu angkot orang tua sendiri tapi beliau memcoba bagaimana susahnya dan belajar mencari uang sendiri, dan selama beliau berada di Jakarta, Cileungsi, Bogor, beliau menjadi seorang buruh pabrik piston.<br><br>Selama beliau bekerja di Jakarta, beliau beranggapan Kehidupan di Jakarta sangat jauh berbeda kehidupan di Jember, waktu terasa begitu lebih cepat berada di Jakarta. beliau harus berangkat dari kontrakan jam 5 pagi  untuk naik angkot, sampai dijalan utama jam setengah 6 dan nunggu bis kota menuju ke tempat kerja dalam perjalan 1,5 hingga 2 jam, tepat disana jam 7.30 pagi. dan masih harus berjalan 1 km lagi untuk sampai di tempat kerja pas jam 8 pagi, beliau bekerja selama 8 jam hingga jam 5 sore dan beliau harus mengulang rutinitas pulang sama seperti berangkatnya, dan tak ada yang bisa dilakukan lagi di kontrakan hanya digunakan untuk beristirahat. dan begitulah rutinitas selama dua tahun yang dilalui, tapi itulah perjuangan, pungkasnya.<br><br>beliau mengatakan \"Jakarta tidak untuk semua orang, hanya untuk orang kuat, gigih, ulet, dan mungkin tidak ada pilihan lain, kalau masih ada opsi sebaiknya jangan ke Jakarta, Jakarta tidak diperuntukkan bagi orang yang tidak siap dari segi fisik dan mental dan waktu terasa lebih cepat, dari segi penghasilan memang lumayan tetapi juga bisa dihabiskan hanya dalam satu malam, bila tidak bisa mengelola dengan baik.<br><br>Setelah dua tahun berada di Jakarta beliau kembali ke Malang karena terdapat insiden adik beliau meninggal dunia karena kecelakaan dan selanjutnya beliau tidak melanjutkan bekerja di Jakarta.(dja)</p>',	7,	'Wahyu_Kurnia_Dewanto.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	'Wahyu_Kurnia_Dewanto.jpg',	NULL,	NULL,	1,	1,	5776,	1,	'2017-05-04 13:10:33',	'2017-05-04 13:10:33',	'2026-11-24 22:47:28',	NULL),
(8,	'Denah Ruang Posisi Dosen JTI',	'denah-ruang-posisi-dosen-jti',	'<p>Bagi mahasiswa yang ingin melakukan bimbingan pada dosen-dosen berikut informasi posisi tempat duduk dosen JTI.</p>\n<p><img style=\"width: 100%;\" src=\"denah_ruang_dosen_1.png\" alt=\"denah_ruang_dosen_1\"></p>',	6,	'denah_dosen_jti.png',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	8108,	1,	'2017-05-08 12:56:29',	'2017-05-08 12:56:29',	'2026-11-24 22:09:59',	NULL),
(12,	'MELATIH DIRI DI BULAN SUCI',	'melatih-diri-di-bulan-suci',	'<p>Selamat Isuk arek2 TI iki;<br>Yukk sumbangkan sebagian rezeki kalian untuk saudara-saudara kita di Yayasan Yabappenatim yang di buka mulai hari ini sampai 17 Juni 2017<br>.<br>OFFICIAL AKUN<br>- Warda Novitasari : 08980432347<br>- Instagram : <a class=\"notranslate\" href=\"https://www.instagram.com/hmjti_polije/\">@hmjti_polije</a><br>- Line : <a class=\"notranslate\" href=\"https://www.instagram.com/ier3344r/\">@ier3344r</a><br>- Facebook : HMJ TI Polije<br>- Email : info.hmjti.polije@gmail.com<br>.<br>- Basecamp :<br>Gedung Teknologi Informasi Lantai 1 (belakang tangga);<br>.<br>Hidup Mahasiswa !<br>Jangan Lupa Produktif</p>\n<blockquote class=\"instagram-media\" style=\"background: #FFF; border: 0; border-radius: 3px; box-shadow: 0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width: 658px; padding: 0; width: calc(100% - 2px);\" data-instgrm-captioned=\"\" data-instgrm-version=\"7\">\n<div style=\"padding: 8px;\">\n<div style=\"background: #F8F8F8; line-height: 0; margin-top: 40px; padding: 50.0% 0; text-align: center; width: 100%;\"> </div>\n<p style=\"margin: 8px 0 0 0; padding: 0 4px;\"><a style=\"color: #000; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: normal; line-height: 17px; text-decoration: none; word-wrap: break-word;\" href=\"https://www.instagram.com/p/BVBLXfbj5pC/\" target=\"_blank\"> . Selamat Isuk arek2 TI iki ?; Yukk sumbangkan sebagian rezeki kalian untuk saudara-saudara kita di Yayasan Yabappenatim yang di buka mulai hari ini sampai 17 Juni 2017 ? . OFFICIAL AKUN ❓ ? Warda Novitasari : 08980432347 ?Instagram : @hmjti_polije ?Line : @ier3344r ?Facebook : HMJ TI Polije ? Email : info.hmjti.polije@gmail.com . ?Basecamp : Gedung Teknologi Informasi Lantai 1 (belakang tangga); . Hidup Mahasiswa ! Jangan Lupa Produktif ?</a></p>\n<p style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; line-height: 17px; margin-bottom: 0; margin-top: 8px; overflow: hidden; padding: 8px 0 7px; text-align: center; text-overflow: ellipsis; white-space: nowrap;\">A post shared by Official Akun HMJ-TI Polije (@hmjti_polije) on <time style=\"font-family: Arial,sans-serif; font-size: 14px; line-height: 17px;\" datetime=\"2017-06-07T00:34:05+00:00\">Jun 6, 2017 at 5:34pm PDT</time></p>\n</div>\n</blockquote>',	9,	'Melatih_Diri_Di_Bulan_Suci.jpg',	1,	0,	2,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	2674,	1,	'2017-06-07 16:09:33',	'2017-06-07 16:09:33',	'2026-11-24 14:20:53',	NULL),
(14,	'Halal Bihalal Idhul Fitri 1438 H Jurusan Teknologi Informasi',	'halal-bihalal-idhul-fitri-1438-h-jurusan-teknologi-informasi',	'<p>Dalam rangka menjalin silaturahmi keluarga jurusan teknologi informasi politeknik negeri jember, pada tanggal 5 Juni 2017 telah terselenggara acara Halal Bihalal Idhul Fitri 1438 H yang di hadiri segenap dosen, teknisi dan staf jurusan teknologi informasi.</p>\n<p> </p>\n<p>Acara ini juga hadir undangan spesial yaitu Direktur Politeknik Negeri Jember Dr. Ir. Nanang Dwi Wahyono, MM, Wakil Direktur I Ir. Abi Bakri, M.Si, Wakil Direktur II Saiful Anwar, S.TP, MP, Wakil Diretur III Moh. Munih Dian Widianta, S.Kom. MT, sekaligus didampingi oleh ketua jurusan teknologi informasi Wahyu Kurnia Dewanto, S.Kom, MT.</p>\n<p> </p>\n<p>Acara ini dipandu oleh pembawa acara yaitu Trismayanti Dwi Puspitasari, S.Kom, M.Cs, semua undangan dengan senang mendatangi acara ini dan memberikan sambutan singkat beserta memberikan info-info terkait program selajutnya di semester ganjil 2017-2018.</p>\n<p> </p>\n<p>Dalam suasana lebaran ini juga tak lupa setelah akhir acara segenap dosen, teknisi dan staf melakukan salaman bersama memohon maaf jika ada salah dan khilaf selama bekerja bersama, dan diakhiri dengan acara ramah tamah di ruang Lobbi gedung jurusan teknologi informasi.</p>\n<p> </p>\n<p>Akhir Kata, Segenap Keluarga Besar Jurusan Teknologi Informasi Mengucapkan Selamat Hari Raya Idhul Fitri 1438 H, Minal Aidzin wal Faidin Mohon Maaf Lahir dan Batin. Semoga kita menjadi insan yang fitri dan bertambah ketakwaan kita kepada Tuhan yang Maha Esa.</p>\n<p> </p>\n<p>Amien.</p>\n<p> </p>\n<p><strong><a title=\"Halal Bihalal Idhul Fitri 1438 H Jurusan Teknologi Informasi\" href=\"http://jti.polije.ac.id/galeri/9-halal-bihalal-idhul-fitri-1438-h-jurusan-teknologi-informasi\" target=\"_blank\">Lihat Galeri</a></strong></p>',	9,	'IMG_19a.jpg',	1,	0,	1,	'Halal Bihalal Idhul Fitri 1438 H Jurusan Teknologi Informasi',	'Djuliar',	NULL,	'IMG_19a.jpg',	'Halal Bihalal Idhul Fitri 1438 H Jurusan Teknologi Informasi',	NULL,	1,	1,	2880,	1,	'2017-07-07 11:27:56',	'2017-07-07 11:27:56',	'2026-11-24 13:10:27',	NULL),
(16,	'Yudisium TI ke XIII Diikuti 99 Lulusan',	'yudisium-ti-ke-xiii-diikuti-99-lulusan',	'<p><strong>Jember</strong>, kemarin 31 Juli 2017, Yudisium Jurusan Teknologi Informasi ke XIII (13, red). telah terselenggara dengan lancar, acara dimulai pada jam 13.00 di Aula Soetrisno Widjaja,</p>\n<p>Acara yudisium dimulai dengan penanyangan galeri kenangan para yudisi yang dikemas ringkas dan tepat membuat para yudisi mengenang semasa mereka kuliah dulu, dilanjutkan acara resmi dengan masuknya parade para dosen dan staf karyawan.</p>\n<p>Kemudian Ketua Jurusan, Wahyu Kurnia Dewanto, S.Kom. MT memberikan sepatah dua patah kata untuk sambutan atas terselenggaranya yudisium ini, tak lupa ketua jurusan mengucapkan selamat kepada para yudisi atas kelulusannya.</p>\n<p>Selanjutnya Sekretaris Jurusan Prawidya Destarianto, S.Kom.MT menuju podium membacakan SK Putusan Direktur Politeknik Negeri Jember tentang Yudisium Jurusan Teknologi Informasi ke XIII.</p>\n<p>Terdapat satu mahasiswa dengan lulusan terbaik pada masing-masing program studi yaitu Agung Muliawan dari Manajemen Informatika dengan IPK 3,82 dengan Dosen pembimbing Ratih Ayuninghemi, S.ST. M.Kom dan Rahardian Arya Prasetya dari Teknik Komputer dengan IPK 3,70 dengan dosen pembimbing Bekti Maryuni, S.Pd.T. M.Kom maju untuk menerima pengharaan dari ketua jurusan teknologin informasi.</p>\n<p>Akhir acara ditutup dengan acara ramah tamah dan persembahan spesial terima kasih dari para yudisi kepada dosen dengan memberikan bunga dan Lagu yang dibawakan oleh Cicin Wahyu Indrawati dan Choiriyah.</p>\n<p>Ketua Panitia, Aji Seto Arifianto, S.ST. M.T mengucapkan terima kasih kepada segenap panitia yang telah berperan serta mensukseskan acara Yudisium Jurusan Teknologi Informasi ke XIII ini. (<strong>djuliar</strong>)</p>',	9,	'DSCF1398.JPG',	1,	0,	1,	'Yudisium Jurusan Teknologi Informasi ke XIII',	'djuliar',	'yudisium, jti, polije',	'DSCF1398.JPG',	'Yudisium Jurusan Teknologi Informasi ke XIII',	'Yudisium TI ke XIII Diikuti 99 Lulusan',	1,	1,	4248,	1,	'2017-08-01 12:54:06',	'2017-08-01 12:54:06',	'2026-11-24 13:27:15',	NULL),
(17,	'Inisiasi Forum Komunikasi Politeknik Bidang Teknologi Informasi',	'inisiasi-forum-komunikasi-politeknik-bidang-teknologi-informasi',	'<p>Dalam rangka peningkatan kapasistas dan kualitas pendidikan politeknik bidang teknologi informasi terutama bagi jurusan Teknologi informasi Politeknik Negeri Jember.  Pada tanggal 3 dan 4 Agustus 2017 dilakukan pertemuan yang dihadiri beberapa perwakilan dari Politeknik Negeri Malang, Politeknik Negeri Jakarta, Politeknik Negeri Sriwijaya, Politeknik Negeri Banyuwangi dengan tema Inisiasi Forum Komunikasi Pendidikan Politeknik Bidang Teknologi Informasi. Adapun yang mendasari pertemuan ini diantaranya untuk mendiskusikan beberapa hal diantaranya</p>\n<ul>\n<li>Permasalahan Generik tentang\n<ul>\n<li>Nomenklatur</li>\n<li>Profil Lulusan</li>\n<li>Standard Kurikulum Bidang TI</li>\n</ul>\n</li>\n<li>Kurangnya pengakuan stake holder terhadap kurikulum dan lulusan pendidikan politeknik</li>\n<li>Keberadaan Asosiasi bidang TI selama ini terlalu luas ruang lingkupnya. ( Universitas, Institut, Pendidikan Vokasi ) perlu kontribusi penguatan <strong>Karakteristik Politeknik.</strong> pada profesi bidang TI</li>\n</ul>\n<p>Hasil diksusi tersebut menghasilkan beberapa hal yaitu:</p>\n<ul>\n<li>Terbentuknya sebuah wadah komunikasi dengan nama “FORUM POLITEKNIK SE INDONESIA BIDANG TEKNIK INFORMATIKA DAN KOMPUTER” dengan formatur sebagai koordinator Bpk. Nur Fauzi Soelaiman ( Politeknik Negeri Jakarta ) dan Sekretaris Bpk. Wahyu Kurnia Dewanto ( Politeknik Negeri Jember )</li>\n<li>Menyepakati diagendakan untuk dilakukan pertemuan kedua di Politeknik Negeri Jakarta yang mengagendakan diskusi tentang beberapa tema yaitu Mapping Kurikulum dan Nomenklatur dan inisiasi kerjasama penelitian dan pengabdian</li>\n</ul>\n<p>Sebagai tindak lanjut dari pertemuan ini Jurusan Teknologi Informasi POLIJE berkomitmen untuk terus mengawal proses pengembangan forum ini agar dapat menjadi forum yang memiliki kontribusi positif baik bagi Kemenristekdikti maupun industri bidang TIK.</p>',	9,	'IMG-20170810-WA0005.jpg',	1,	0,	1,	'Inisiasi Forum Komunikasi Politeknik Bidang Teknologi Informasi',	'djuliar, admin',	'inisiasi, forum, polije, politeknik, ti',	'IMG-20170810-WA0005.jpg',	'Inisiasi Forum Komunikasi Politeknik Bidang Teknologi Informasi',	'Inisiasi Forum Komunikasi Politeknik Bidang Teknologi Informasi',	1,	1,	3614,	1,	'2017-08-04 09:27:36',	'2017-08-04 09:27:36',	'2026-11-24 14:50:21',	NULL),
(18,	'Pelepasan Wisudawan oleh Jurusan Teknologi Informasi',	'pelepasan-wisudawan-oleh-jurusan-teknologi-informasi',	'<p>Sabtu, 5 Agustus 2017 menjadi saksi sejarah Keluarga Besar Jurusan Teknologi Informasi Polije melakukan tradisi baru yaitu melakukan pelepasan wisudawan yang diikuti oleh 99 wisudawan dan segenap keluarga jurusan TI dan HMJTI, hal ini merupakan sebuah tradisi baru dimana sebelum-sebelumnya dari pihak jurusan tidak pernah melepas secara simbolis wisudawan yang telah lulus.</p>\n<p>Pada hari tersebut bisa dijadikan sebagai hari kebangkitan solidaritas Satu TI dalam bentuk semarak dan arak arakan wisuda TI 2017.</p>\n<p>Diawali wisudawan berkumpul di gedung jurusan TI bersama segenap anggota HMJTI, para wisudawan berjalan menuju GOR Perjuangan 45 tempat acara wisuda berlangsung.  Sebelum memasuki ruangan acara wisuda para wisudawan berbaris dengan rapi mendengarkan arahan dari pihak jurusan TI oleh Sekretaris Jurusan Prawidya Destarianto, S.Kom. MT. selanjutnya masuk ke ruangan untuk mengikuti sidang terbuka wisuda Politeknik Negeri Jember.</p>\n<p>Akhir kata terima kasih atas partisipasi semua pihak dalam mensukseskan acara tersebut. kita luar biasa. Kita adalah pengukir sejarah baru dan tradisi ini harus kita jaga seterusnya.</p>\n<p>Selamat jalan kawan! dunia yang lebih luas telah menunggumu untuk kau jelajahi.</p>',	10,	'IMG-20170807-WA0002.jpg',	1,	0,	1,	'Pelepasan Wisudawan oleh Jurusan Teknologi Informasi',	'djuliar, admin',	'wisuda, polije, ti, ',	'IMG-20170807-WA0002.jpg',	'Pelepasan Wisudawan oleh Jurusan Teknologi Informasi',	'Pelepasan Wisudawan oleh Jurusan Teknologi Informasi',	1,	1,	5235,	1,	'2017-08-07 10:54:25',	'2017-08-07 10:54:25',	'2026-11-24 12:06:09',	NULL),
(20,	'Pembayaran SPP dan Her Registrasi Semester Ganjil 2017/2018',	'pembayaran-spp-dan-her-registrasi-semester-ganjil-2017-2018',	'<p>PENGUMUMAN</p>\n<p>Diberitahukan kepada Mahasiswa Politeknik Negeri Jember (termasuk yang sedang melaksanakan tugas akhir dan PKL) semester ganjil Tahun Akademilk 2017/2018</p>\n<p>DIWAJIBKAN</p>\n<p>Untuk Daftar Ulang / Her Registrasi</p>\n<ol>\n<li>Pembayaran SPP dan Her Registrasi semester ganjil 2017/2018 mulai tanggal 7 s.d. 31 Agustus 2017</li>\n<li>Bagi Mahasiswa yang terlambat Daftar Ulang atau Her Registrasi dikenakan denda 10% dari UKT</li>\n<li>Apabila sampai dengan tanggal 6 September 2017 tidak Her Registrasi maka mahasiswa akan dicutikan dengan denda 20% dari UKT</li>\n</ol>',	6,	'IMG_20170808_170638.jpg',	1,	0,	0,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	4040,	1,	'2017-08-10 09:32:43',	'2017-08-10 09:32:43',	'2026-11-25 01:42:22',	NULL),
(25,	'Kegiatan Pengenalan Kampus Mahasiswa Jurusan Teknologi Informasi',	'kegiatan-pengenalan-kampus-mahasiswa-jurusan-teknologi-informasi',	'<p>Setelah rangkaian kegiatan Pengenalan Kehidupan Kampus bagi Mahasiswa Baru (<strong>PKKMB</strong>) dan Bela Negara tahun 2017 oleh Politeknik Negeri Jember, pada tanggal 30 Agustus 2017 di penghujung bulan ini Jurusan Teknologi Informasi mendapatkan kesempatan bertemu langsung ke mahasiswa baru khususnya mahasiswa yang telah lolos masuk dalam Jurusan Teknologi Informasi dalam acara Program Pengenalan Jurusan yang diselenggrakan di GOR Perjuangan 45 Polije. Acara ini dihadiri oleh segenap dosen, karyawan dan teknisi untuk memberikan sambutan dan perkenalan kepada mahasiswa baru.</p>\n<p>Dalam acara tersebut bertujuan agar mahasiswa baru mendapat wawasan luas tentang jurusan dan program studi yang mereka pilih, diawali oleh sambutan oleh ketua jurusan Wahyu Kurnia Dewanto, S.Kom.MT, mahasiswa dengan seksama mendengarkan sambutan beliau. Acara dilanjutkan dengan melakukan perkenalan satu persatu keluarga besar Jurusan Teknologi Informasi dimulai dari dosen, teknisi dan staf administrasi.</p>\n<p>Setelah istirahat, dilanjutkan dengan pengenalan Program Studi dengan pemateri oleh masing-masing Ketua Program Studi yaitu, Dwi Putro Sarwo Setyohadi,S.Kom. M.Kom memberikan materi untuk prodi Manajemen Informatika, Hairyono Rakhmad, S.Pd. M.Kom memberikan materi untuk prodi Teknik Komputer, Elly Antika, S.T. M.Kom memberikan materi untuk prodi D4 Teknik Informatika.</p>\n<p>Akhir acara mahasiswa baru berbaris menuju ke Gedung Jurusan Teknologi Informasi untuk melakukan kunjungan langsung untuk mengetahui lokasi dan tempat kuliah dan laboratorium ketika nantinya mahasiswa melakukan aktivitas belajar mengajar.</p>\n<p><strong>(djuliar)</strong></p>',	10,	'IMG_20170830_073952.jpg',	1,	0,	1,	'Kegiatan Pengenalan Kampus Mahasiswa Jurusan Teknologi Informasi',	'djuliar',	'pkkmb, jti, polije',	'IMG_20170830_073952.jpg',	'Kegiatan Pengenalan Kampus Mahasiswa Jurusan Teknologi Informasi',	NULL,	1,	1,	5081,	1,	'2017-08-30 10:49:46',	'2017-08-30 10:49:46',	'2026-11-24 21:07:15',	NULL),
(26,	'In House Training Sistem Informasi Geografis oleh Prof. Dr. Indarto, STP, DEA',	'in-house-training-sistem-informasi-geografis-oleh-prof-dr-indarto-stp-dea',	'<p>Dalam rangka peningkatan kualitas perguruan tinggi khususnya dosen dan teknisi Jurusan Teknologi Informasi mengadakan In House Training Sistem Informasi Geografis pada Hari Selasa dan Rabu tanggal 5-6 September 2017 yang diselenggarakan di Lab. Rekayasa Sistem Informasi Gedung Jurusan Teknologi Informasi.</p>\n<p>Kegiatan ini dipandu oleh pembawa acara Trismayanti Dwi, S.Kom, M.Cs yang dimulai oleh beberapa patah kata sambutan oleh ketua Jurusan Teknologi Informasi, Wahyu Kurnia Dewanto, S.Kom, MT dan Wakil Direktur 2 Bidang Administrasi Umum yaitu Saiful Anwar, S.TP, MP dan dilanjutkan pengantar oleh Prof. Dr. Indarto, STP, DEA tentang beberapa pengetahuan dasar sistem informasi geografis.</p>\n<p>Prof. Dr. Indarto, STP, DEA menyampaikan dalam pelatihan ini yang lebih penting adalah latihannya bukan pelatihannya, karena jika tidak disertai latihan dari masing-masing peserta maka ilmu yang akan disampaikan nantinya tidak bisa diserap secara maksimal.</p>\n<p>Kegiatan ini dihadiri oleh 20 peserta dari dosen dan teknisi internal Politeknik Negeri Jember dan tiga orang dari pendamping pemateri dari Universitas Jember. Training direncanakan akan terlaksana hingga hari Rabu besok jam 15.00 WIB.</p>\n<p><strong>(djuliar)</strong></p>\n<p> </p>',	9,	'IMG_20170905_085006.jpg',	1,	0,	1,	'In House Training Sistem Informasi Geografis oleh Prof. Dr. Indarto, STP, DEA',	'djuliar',	'sig, jti, polije, djuliar',	'IMG_20170905_085006.jpg',	'In House Training Sistem Informasi Geografis oleh Prof. Dr. Indarto, STP, DEA',	'In House Training Sistem Informasi Geografis oleh Prof. Dr. Indarto, STP, DEA',	1,	1,	3278,	1,	'2017-09-05 11:32:33',	'2017-09-05 11:32:33',	'2026-11-24 19:00:54',	NULL),
(27,	'[Hari Ke-2] In House Training Sistem Informasi Geografis Turun Langsung ke Lapangan',	'hari-ke-2-in-house-training-sistem-informasi-geografis-turun-langsung-ke-lapangan',	'<p>Pada hari sebelumnya tentang <strong><a title=\"In House Training Sistem Informasi Geografis oleh Prof. Dr. Indarto, STP, DEA\" href=\"http://jti.polije.ac.id/artikel/26-in-house-training-sistem-informasi-geografis-oleh-prof-dr-indarto-stp-dea\" target=\"_blank\">In House Training Sistem Informasi Geografis oleh Prof. Dr. Indarto, STP, DEA</a></strong>, peserta mengikuti kegiatan ini hanya berada di Lab. Rekayasa Sistem Informasi dimana kegiatan ini diselenggarakan, pada hari kedua ini peserta ditugaskan untuk terjun langsung ke lapangan untuk melakukan <em>tracking </em>lokasi untuk melakukan pemetaan.</p>\n<p> </p>\n<p>Peserta dari 19 orang dibagi menjadi 3 kelompok dengan masing-masing tugasnya, kelompok 1 melakukan pemetaan wilayah untuk lokasi sekitar POLIJE, kelompok 2 melakukan pemetaan untuk gedung-gedung yang berada di dalam lingkungan POLIJE, dan kelompok 3 melakukan pemetaan rute atau jalan yang berada di dalam lingkungan POLIJE.</p>\n<p> </p>\n<p>Masing-masing didampingi oleh 3 orang instruktur yang mendampingi dan peserta juga diberikan sebuah GPS (<em>Global Positioning System</em>) untuk menyimpan hasil <em>tracking </em>yang kelompok ini lalui dengan tujuan nantinya hasil dari <em>tracking </em>GPS bisa di import ke komputer untuk pengolahan lebih lanjut.</p>\n<p> </p>\n<p>Setelah semua kelompok selesai penyusuran lokasi, lalu kembali ke Lab. Rekayasa Sistem Informasi sembari istirahat <em>coffe break</em>, peserta kembali melanjutkan kegiatan pelatihan SIG untuk mengimport hasil tinjau lapangan tadi.</p>\n<p> </p>\n<p>Pada akhir kegiatan peserta diberi ujian evaluasi atas semua materi yang diberikan untuk dilakukan penilaian dan juga mengisi beberapa kuisioner tentang pesan dan kesan pada kegiatan kali ini.<br><strong>(djuliar)</strong></p>\n<p> </p>',	9,	'IMG_20170906_084607.jpg',	1,	0,	1,	'[Hari Ke-2] In House Training Sistem Informasi Geografis Turun Langsung ke Lapangan',	'djuliar',	'sig, jti, polije,',	'IMG_20170906_084607.jpg',	'[Hari Ke-2] In House Training Sistem Informasi Geografis Turun Langsung ke Lapangan',	'[Hari Ke-2] In House Training Sistem Informasi Geografis Turun Langsung ke Lapangan',	1,	1,	2575,	1,	'2017-09-07 15:03:37',	'2017-09-07 15:03:37',	'2026-11-24 22:24:11',	NULL),
(28,	'Pelepasan Mahasiswa Manajemen Informatika Program Dual Degree Ke China',	'pelepasan-mahasiswa-manajemen-informatika-program-dual-degree-ke-china',	'<p>Dalam rangka mewujudkan visi Politeknik Negeri Jember menjadi Politeknik Terkemuka Tingkat Asia pada tahun 2025, Jurusan Teknologi Informasi bekerja sama dengan Changzhou Vocational Institute of Mechatronic Technology, Jiangsu, China dengan membuka Program Dual Degree melalui seleksi ketat yang telah diikuti oleh 5 orang mahasiswa dari Program Studi Manajemen Informatika, yaitu :</p>\n<p> </p>\n<ol>\n<li style=\"padding-left: 30px;\">Suargita Rediana Madasari (E31161214)</li>\n<li style=\"padding-left: 30px;\">Abdillah Syaifuddin Basarsah (E31161689)</li>\n<li style=\"padding-left: 30px;\">Mohammad Azman (E31161642)</li>\n<li style=\"padding-left: 30px;\">Defredo Oyvind Yogaprawira (E31161812)</li>\n<li style=\"padding-left: 30px;\">Yusril Fathurrohman (E31160722)</li>\n</ol>\n<p> </p>\n<p>Hari ini, 18 September 2017 Ketua Jurusan Teknologi Informasi, Wahyu Kurnia Dewanto, S.Kom, MT., didampingi oleh Sekretaris Jurusan Prawidya Destarianto, S.Kom, MT., dan Ketua Program Studi Dwi Putro Sarwo S, S.Kom, M.Kom, mengadakan acara ceremonial pelepasan mahasiswa Program Dual Degree, ketua jurusan memberikan pengarahan kepada mahasiswa terkait agar bisa beradaptasi dengan baik dari suasana akademik maupun suasana sosial yang berada di China.</p>\n<p> </p>\n<p>Sekretaris jurusan memberikan pengarahan agar mahasiswa selalu menjaga kesehatan agar bisa mengikuti kegiatan akademik dengan lancar. Setelah itu tak lupa pula ketua program studi juga memberikan arahan bahwa mahasiswa diharapkan bisa bersaing dan belajar dengan giat dalam mengikuti kegiatan perkuliahan agar bisa beradaptasi dengan baik dengan atmosfer pendidikan yang diajarakan di kampus tersebut.</p>\n<p> </p>\n<p>Keberangkatan mahasiswa Manajemen Informatika Program Dual Degree ini dijadwalkan pada hari Sabtu 23 September 2017 dari Jember menuju ke Jakarta dan akan dilakukan pengarahan awal di hotel IBIS JAKARTA sebelum mereka diberangkatkan Shanghai, China.</p>',	8,	'Pelepasan_Program_Dual_Degree.jpg',	1,	0,	1,	'Pelepasan Mahasiswa Manajemen Informatika Program Dual Degree Ke China',	'djuliar',	'djuliar, jti, polije, mif',	'Pelepasan_Program_Dual_Degree.jpg',	'Pelepasan Mahasiswa Manajemen Informatika Program Dual Degree Ke China',	'Pelepasan Mahasiswa Manajemen Informatika Program Dual Degree Ke China',	1,	1,	4456,	1,	'2017-09-18 13:51:33',	'2017-09-18 13:51:33',	'2026-11-24 18:59:34',	NULL),
(29,	'Info Kegiatan Mahasiswa Dual Degree Manajemen Informatika di China',	'info-kegiatan-mahasiswa-dual-degree-manajemen-informatika-di-china',	'<p>Setelah hampir 2 minggu meninggalkan tanah air Indonesia, mahasiswa Manajemen Infomatika Dual Degree di Changzhou Vocational Institute of Mechatronic Technology memberikan sekilas kegiatan terbaru mereka disana.</p>\n<p> </p>\n<p>Pada dasarnya mereka sudah bisa berkomunikasi dengan baik dengan atmosfer perkuliahan disana, mereka masih libur 1 minggu kuliah dikarenakan ada perayaan Hari Kemerdekaan China.</p>\n<p> </p>\n<p>Kegiatan perkuliahan disana sangat disiplin sekali dan tepat waktu. Pada saatnya masuk semua mahasiswa tidak ada yang berkeliaran di luar ruangan, hingga waktu istirahat terdapat waktu yang ditentukan. terdapat kantin yang hanya melayani pada saat waktu istirahat.</p>\n<p> </p>\n<p>Hal yang menarik adalah ketika berada di kantin sistem pembayaran sudah tidak menggunakan uang tunai sebagai alat pembayaran, tetapi menggunakan aplikasi pada sebuah smartphone, ketika membayar tinggal menscan barcode, otomatis saldo uang yang berada pada aplikasi berkurang dengan sendirinya. Selain itu terdapat pembayaran dengan menggunakan semacam KTM (Kartu Tanda Mahasiswa) yang juga berisi saldo uang untuk pembayaran yang bisa digunakan pembelian di outlet disekitar kampus.<br><br></p>\n<p>Berikut sekilas informasi kehidupan mahasiswa Manajemen Informatika Dual Degree yang Administrator dapatkan dari salah satu peserta program Dual Degree (Abdi).</p>\n<p><strong>(Djuliar)</strong></p>',	6,	'Dual_Degree_2.jpg',	1,	0,	1,	'Info Kegiatan Mahasiswa Dual Degree Manajemen Informatika di China',	'djuliar',	'jti, china, polije,',	'Dual_Degree_2.jpg',	'Info Kegiatan Mahasiswa Dual Degree Manajemen Informatika di China',	'Info Kegiatan Mahasiswa Dual Degree Manajemen Informatika di China',	1,	1,	5193,	1,	'2017-10-04 12:41:42',	'2017-10-04 12:41:42',	'2026-11-24 18:58:19',	NULL),
(30,	'TEKNOLOGI INFORMASI BERHASIL MENJADI RUNNER UP TURNAMEN FUTSAL',	'teknologi-informasi-berhasil-menjadi-runner-up-turnamen-futsal',	'<p style=\"text-align: justify;\">Perhelatan turnamen futsal 2017 antar jurusan di Politeknik Negeri Jember dalam rangka Dies Natalis yang diadakan oleh UKM Olahraga menjadi momen bersejarah bagi Jurusan Teknologi Informasi. Tim Futsal Jurusan Teknologi Informasi berhasil menorehkan prestasi yang membanggakan dengan menjadi Runner up dalam turnamen tersebut.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Pada partai final, pasukan Teknologi Informasi harus mengakui keunggulan tim Jurusan Peternakan, minggu (8/10/2017) malam hari. Tetapi, selama turnamen berlangsung, para pemain membuktikan kehebatan dan perjuangan yang begitu luar biasa dengan menyingkirkan satu per satu lawan dalam setiap pertandingan hingga mencapai babak final. Tentu hal ini menjadi suatu kebanggaan tersendiri bagi jurusan kita.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Selain itu, prestasi luar biasa juga ditorehkan oleh <em><span style=\"color: #ff0000;\">Ahmad Rizkianto</span></em> salah satu pemain yang menjadi Top Skor atau pencetak gol terbanyak kategori futsal jurusan dalam turnamen tersebut. Pencapaian tersebut menambah tropi yang diterima oleh tim futsal Jurusan Teknologi Informasi.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Dibalik semua itu, kesuksesan tim juga tidak lepas dari dukungan para suporter yang begitu setia dan bangga dalam mengawal perjuangan para pemain. Sejak awal turnamen digelar mereka selalu memberikan dukungan dan doa seraya menyanyikan lagu-lagu penyemangat dan kemenangan untuk tim futsal Teknologi Informasi tercinta. Terimakasih atas segala perjuangan dan kerja keras semua pihak dalam mengharumkan nama jurusan Teknologi Informasi. Semoga prestasi lainnya bisa kita raih di berbagai kesempatan dan kebersamaan semua masyarakat Teknologi Informasi semakin solid.</p>',	8,	'juara_futsal.jpg',	1,	0,	2,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3643,	1,	'2017-10-09 03:20:08',	'2017-10-09 03:20:08',	'2026-11-24 19:00:04',	NULL),
(31,	'Kerjasama Jurusan TI dengan Perguruan Tinggi Management Science University (MSU) Malaysia',	'kerjasama-jurusan-ti-dengan-perguruan-tinggi-management-science-university-msu-malaysia',	'<p>Sebagai upaya untuk mengembangkan kampus Politeknik Negeri Jember menuju <em>Class of International University</em>, maka terus diperluas kerjasama dengan berbagai perguruan tinggi luar negeri. Jurusan Teknologi Informasi merupakan salah satu jurusan yang sedang menjajaki kerjasama dengan perguruan tinggi luar negeri. Setelah berproses kerjasama dengan Kyungpook National University (KNU) Korea Selatan, maka dilanjutkan dengan perguruan tinggi Management Science University (MSU) Malaysia.</p>\n<p> </p>\n<p>Bertempat di ruang sidang pimpinan, pada hari Jumat, 06 Oktober 2017 Direktur Polije Dr. Ir. Nanang Dwi Wahyono, MM didampingi Wakil Direktur Bidang Akademik Ir. Abi Bakri, M.Si, Wakil Direktur Bidang Kemahasiswaan, Kepala Badan Kerjasama Dr. Ir. Nantil Bambang Eko Sulistiyono, M.Si dan Koordinator kerjasama luar negeri Agung Wahyono, Ph.D bertemu dengan perwakilan dari Management Science University (MSU) Malaysia yaitu Prof Eddy Yusuf, Ph.D.</p>\n<p> </p>\n<p>Dalam pertemuan tersebut dibahas mengenai konsep kerjasama students exchange, dual degree dan transfer credit semester. Didalam pertemuan tersebut hadir pula Sekretaris Jurusan Teknologi Informasi Prawidya Destarianto, S.Kom, MT, Ketua Jurusan Kesehatan Sustin Farlinda, S.Kom, MT, Ketua Program Studi D3 Gizi Klinik Ir. Rindiani, MP, Ketua Jurusan Bahasa Komunikasi dan Pariwisata Siti Aisyah, M.Pd dan Sekretaris Jurusan Bahasa Komunikasi dan Pariwisata Enik Rukiyati, M.Pd.</p>\n<p> </p>\n<p>Diharapkan dengan adanya rintisan kerjasama ini, mahasiswa di Politeknik Negeri Jember dapat semakin berkembang bidang keilmuannya dan mendukung visi Menjadi Politeknik Terkemuka Tingkat Asia pada tahun 2025.</p>\n<p><strong>(rian)</strong></p>',	10,	'kerjasama-msu-malaysia_2.jpeg',	1,	0,	1,	'Kerjasama Jurusan TI dengan Perguruan Tinggi Management Science University (MSU) Malaysia',	'djuliar',	'jti, polije, msu, malaysia',	'kerjasama-msu-malaysia_2.jpeg',	'Kerjasama Jurusan TI dengan Perguruan Tinggi Management Science University (MSU) Malaysia',	'Kerjasama Jurusan TI dengan Perguruan Tinggi Management Science University (MSU) Malaysia',	1,	1,	4285,	1,	'2017-10-09 12:44:43',	'2017-10-09 12:44:43',	'2026-11-24 18:59:47',	NULL),
(33,	'Raih Tiga Medali Emas Kejurnas Silat Perisai Diri Piala Presiden 2017',	'raih-tiga-medali-emas-kejurnas-silat-perisai-diri-piala-presiden-2017',	'<p style=\"text-align: justify;\">Mahasiswa Jurusan Teknologi Informasi kembali memberikan prestasi membanggakan di bidang olahraga tingkat nasional yaitu cabang pencak silat. Empat orang mahasiswa  Jurusan Teknologi Informasi sebagai perwakilan Politeknik Negeri Jember pada Kejuaraan Nasional Silat Perisai Diri Antar Perguruan Tinggi Piala Presiden 2017 yang digelar pada 27 September – 2 Oktober 2017 di Universitas PGRI Adibuana Surabaya berhasil menyumbangkan tiga medali emas dalam kejuaran tersebut, yang sekaligus menjadikan Politeknik Negeri Jember sebagai Juara Umum III.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Mereka adalah <strong>M. Faruq Wahyudi</strong> ( 1 medali emas seni tunggal putra dan 1 medali emas berpasangan senjata putra), <strong>Kia Dzaky</strong> ( 1 medali emas beregu putra), <strong>Sofia Fitria Sandi</strong> dan <strong>Bawik Ardian</strong>. Keempat atlet tersebut bersaing dengan 400 atlet dari 28 perguruan tinggi se-Indonesia.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Selain itu, berkat pencapaian prestasi M. Faruq Wahyudi yang begitu gemilang pada kejuaran tersebut membuat dia terpilih menjadi salah satu atlet silat delegasi Indonesia pada Kejuaran Perisai Diri International Championship 2017 yang berlangsung di Indonesia sebagai tuan rumah dan diikuti oleh ratusan atlet silat dari berbagai negara pada tanggal 26 Oktober - 2 November 2017 mendatang (lihat <a href=\"http://www.pdic2017.com\">www.pdic2017.com</a>).</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Selamat atas prestasi yang telah dicapai, semoga dengan prestasi ini akan meningkatkan semangat kompetisi bagi mahasiswa lainnya dalam mengembangkan bakat dan minat yang dimiliki untuk mengharumkan nama Politeknik Negeri Jember, terutama Jurusan Teknologi Informasi. <strong>(Misbah)</strong></p>',	8,	'kejurnas2017_11.jpg',	1,	0,	2,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	4899,	1,	'2017-10-11 02:11:59',	'2017-10-11 02:11:59',	'2026-11-24 19:00:09',	NULL),
(34,	'Mahasiswa Teknologi Informasi Berkiprah dalam Google Firebase Appfest Hackathon Jakarta 2017',	'mahasiswa-teknologi-informasi-berkiprah-dalam-google-firebase-appfest-hackathon-jakarta-2017',	'<p style=\"text-align: justify;\">Indonesia kembali mendapatkan kesempatan dari Google untuk mengoptimalkan perkembangan dunia digital melalui event Google Firebase Appfest Hackathon. Acara ini diselenggarakan untuk pertama kalinya di Indonesia pada Rabu, 18 Oktober 2017 bertempat di Ayana Midplaza, Jakarta.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Pada kegiatan tersebut, Mahasiswa Jurusan Teknologi Informasi kembali menunjukan kemampuan dan eksistensinya dengan menjadi salah satu dari 25 tim yang dipilih oleh Google untuk mengikuti kegiatan hackathon tersebut. Mereka adalah <strong>Ahmad Syamsul Arifin</strong>, <strong>Risqi Ahmad Sultoni</strong>, dan <strong>Muhammad Ja’far Abdillah</strong>.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Ketiga mahasiswa Program Studi Teknik Informatika semester 5 tersebut harus bersaing dengan programmer lainnya dari seluruh Indonesia untuk membuat sebuah aplikasi menggunakan infrastruktur Firebase selama 6 jam. <em><strong>Move it</strong> </em>adalah aplikasi android yang mereka kembangkan dengan memberikan solusi dalam bidang kesehatan, khususnya lifestyle masyarakat agar lebih tertarik untuk berolahraga dengan mempertemukan antar penggiat olahraga dalam melakukan aktivitas olahraga bersama.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Selain itu, mereka juga mendapatkan wawasan secara langsung dari para penggerak google seperti Thomas Bouldin (Technical Lead Google), Dennis Alund ( Google Developer Expert), Michael Haney (Software Engineer Google) dan masih banyak lainnya sebagai bekal dan ilmu dalam mengembangkan produk menggunakan Firebase dalam memberikan solusi terhadap permasalahan di Indonesia.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Mereka menyampaikan rasa syukur dan bahagia mendapatkan kesempatan tersebut. “Kami sangat bahagia dapat diundang dalam kegiatan tersebut dengan mendapatkan dukungan dari pihak kampus dan mampu bersaing dengan peserta lainya yang mayoritas berasal dari kalangan startup dan programmer profesional” ungkap Ari.</p>\n<p style=\"text-align: justify;\"> </p>\n<p style=\"text-align: justify;\">Harapannya, Mahasiswa Jurusan Teknologi Informasi harus lebih berani dalam berkreasi untuk memberikan solusi permasalahan sesuai kemampuannya. Karena kemampuan kita tidak kalah dengan para programmer atau mahasiswa yang ada diluar sana.</p>',	8,	'Firebase.jpeg',	1,	0,	2,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3115,	1,	'2017-10-21 16:05:39',	'2017-10-21 16:05:39',	'2026-11-24 22:39:20',	NULL),
(35,	'Kunjungan Kerjasama JTI Politeknik Negeri Jember dengan Management Science University (MSU) Malaysia',	'kunjungan-kerjasama-jti-politeknik-negeri-jember-dengan-management-science-university-msu-malaysia',	'<p>Pada tanggal 15 - 17 November 2017 Direktur Politeknik Negeri Jember Dr. Ir. Nanang Dwi Wahyono, MM dan Wakil Direktur Bidang Akademik Ir. Abi Bakri, M.Si beserta Koordinator Bidang Kerjasama Luar Negeri Agung Wahyono, Ph.D didampingi Ketua Jurusan Teknologi Informasi Wahyu Kurnia Dewanto, S.Kom, MT melakukan kunjungan ke kampus Management Science University (MSU) Malaysia. Kegiatan ini bertujuan untuk menindaklanjuti kesepakatan kerjasama MoU diantara kedua belah pihak.</p>\n<p><br>Dalam kegiatan tersebut pihak kampus Management Science University (MSU) Malaysia dihadiri langsung oleh President MSU Prof Tan Sri Dato Wira DR Mohd Shukri Ab Yajid dan Dean Faculty of Information Sciences and Engineering (FISE) Prof DR Adam Amril Jaharadak didampingi Head of International Office Prof Eddy Yusuf, Ph.D beserta jajaran pimpinan unit lainnya di MSU.</p>\n<p><br>Dengan adanya MoU ini, Jurusan Teknologi Informasi dapat berperan aktif dan langsung untuk mendukung visi Politeknik Negeri Jember menjadi Politeknik Terkemuka Tingkat Asia pada Tahun 2025 dan pengembangan kampus menuju Class of International University, dimana sebelumnya telah dilaksanakan juga kerjasama dengan Kyungpook National University (KNU) Korea Selatan dan Changzhou Institute of Mechatronic Technology China.</p>',	6,	'image31.jpeg',	1,	0,	1,	NULL,	'djuliar, ryan',	'Polije, msu, malaysia,jti,',	'image31.jpeg',	'Kunjungan Kerjasama JTI Politeknik Negeri Jember dengan Management Science University (MSU) Malaysia',	'Kunjungan Kerjasama JTI Politeknik Negeri Jember dengan Management Science University (MSU) Malaysia',	1,	1,	4122,	1,	'2017-11-20 09:25:14',	'2017-11-20 09:25:14',	'2026-11-24 18:59:06',	NULL),
(36,	'Yudisium Ke XIV Jurusan Teknologi Informasi',	'yudisium-ke-xiv-jurusan-teknologi-informasi',	'<p>Dengan puji syukur ke hadirat Tuhan YME, Yudisium ke XIV sukses diselenggarakan dengan lancar. Kemarin tepat tanggal 22 November 2017 Jam 7 pagi Yudisium ke XIV yang diikuti oleh 95 orang yudisi dengan rincian 43 yudisi Program Studi Manajemen Informatika dan 52 yudisi Program Studi Teknik Komputer.</p>\n<p><br>Pra-acara dimulai dengan pemutaran video slideshow kenangan para yudisi selama mereka menempuh lika liku kehidupan kampus. Para yudisi dengan fokus melihat satu persatu foto kenangan dengan berbagai ekspresi dan emosi masing-masing.</p>\n<p><br>Acara resmi dimulai dari masuknya barisan ketua jurusan, sekretaris jurusan, ketua program studi, dosen dan teknisi yang diiringi oleh lagu Bagimu Negeri. Demi khitmatnya acara pembacaan doa yang di bawakan oleh Bapak Agus Santoso A.Md. agar acara berjalan dengan lancar. dan dilanjutkan dengan menyanyikan Lagu Indonesia Raya dan Mars Polije.</p>\n<p><br>Selanjutnya, Sekretaris Jurusan Prawidya Destarianto, S.Kom. MT membaca Surat Keputusan Yudisium tentang mahasiswa yang namanya tertera pada putusan tersebut telah dinyatakan lulus dari Politeknik Negeri Jember.</p>\n<p><br>Acara dilanjutkan dengan pelepasan secara simbolis para yudisi oleh masing-masing program studi dan ketua jurusan Teknologi Informasi dengan maju satu persatu untuk diberikan sertifikat kelulusan mereka. dan tak lupa pula disela acara tersebut terdapat kejutan sambutan dari perwakilan yudisi mempersembahkan sebuah lagu khusus untuk dosen yang hadir kala itu, diantara yudisi juga memberikan bunga kepada dosen sebagai bukti rasa terima kasih atas segala ilmu yang telah diberikan selama ini.</p>\n<p><br>Setelah acara kejutan dari para yudisi, sekretaris jurusan kembali maju menuju podium untuk menyampaikan surat keputusan tentang Yudisi yang menerima predikat terbaik dari masing-masing program studi yaitu Nurinda Febriani dengan IPK 3,75 dari Manajemen Informatika dan Khoiruddin Bahderu Thamam dengan IPK 3,72 dari Teknik Komputer.</p>\n<p><br>Akhir acara, dilakukan sesi foto bersama dosen, teknisi dan para yudisi untuk memberikan kenangan dan dokumentasi dari kegiatan Yudisium ke XIV.</p>\n<p>Acara ini sukses terselenggara atas arahan dengan sabar dari Ketua Panitia Ibu Trismayanti Dwi P, S.Kom. M.Cs. beliau menyampaikan banyak terima kasih atas segenap panitia dan segenap yang terlibat dalam acara tersebut, acara tidak akan terselenggara dengan lancar tanpa kekompakan panitia sekalian.</p>',	9,	'IMG_9878.JPG',	1,	0,	1,	'Yudisium Ke XIV Jurusan Teknologi Informasi',	'djuliar',	'djuliar, jti, polije,yudisium,wisuda',	'IMG_9878.JPG',	'Yudisium Ke XIV Jurusan Teknologi Informasi',	'Yudisium Ke XIV Jurusan Teknologi Informasi',	1,	1,	2915,	1,	'2017-11-23 10:00:45',	'2017-11-23 10:00:45',	'2026-11-24 19:01:43',	NULL),
(37,	'2nd IT Exhibition 2018',	'2nd-it-exhibition-2018',	'<p>IT Exhibition ini merupakan suatu kegiatan akhir dari perkuliahan dengan tujuan melakukan pelaporan dalam bentuk pameran produk tugas akhir atau mempublikasikan karya mahasiswa. Kegiatan yang diberi tema \"Pursue Your Future With IT\" ini telah dilaksanakan yang kedua kalinya, pada IT Exhibition yang pertama hanya diikuti oleh Program Studi D4 Teknik Informatika saja sedangkan pada yang kegiatan yang kedua ini diikuti oleh semua program studi di Jurusan Teknologi Informasi baik Manajemen Informatika dan Teknik Komputer.</p>\n<p> </p>\n<p>Kegiatan ini dilaksanakan selama dua hari pada 17 dan 18 Januari 2018, pada hari pertama peserta dari program studi TIF semester 1 dan TIF Semester 5, sedangkan pada hari kedua diikuti oleh program studi TIF semester 3, MIF semester 3 dan TKK.</p>\n<p> </p>\n<p>Karya yang ditampilkan pada kegiatan kali ini yaitu remastering sistem operasi dan aplikasi desktop oleh TIF semester 1, Web dan Aplikasi mobile oleh TIF dan MIF Semester 3, Web dan Mobile yang sudah bekerja sama dengan pihak stakeholder oleh TIF semester 5, dan TKK mempubilkasikan karya rangkaian elektronik dan modul otomasi.</p>\n<p> </p>\n<p>Ketua Jurusan, Wahyu Kurnia Dewanto, sangat mendukung kegiatan kali ini karena ini menjadi media mempromosikan aktifitas dan produk yang telah dihasilkan mahasiswa. Harapan dari kegiatan ini yaitu dengan mengundang stakeholder dari luar agar pada saat Praktek Kerja Lapang (PKL) atau magang industri stakeholder dapat memanfaatkan sesuai dengan bidang yang ditekuni. begitu juga dengan memperkenalkan karya mahasiswa ini khususnya mahasiswa tingkat akhir, harapan kami kita bisa mengenal dan tahu potensi mereka dan bisa di serap oleh stakeholder pada dunia kerja dan masyarakat.</p>\n<p> </p>\n<p>Ini merupakan strategi dari kami khususnya untuk mempromosikan produk dan potensi mahasiswa kami atau calon alumni kepada stakeholder dan masyarakat, dan kegiatan ini akan kami lanjutkan nantinya pada tahun-tahun berikutnya dan akan kita tingkatkan kualitas kegiatan ini.</p>\n<p> </p>',	9,	'Pameran_200x300_L.png',	1,	0,	1,	'2nd IT Exhibition 2018',	'djuliar',	'jti, polije, djuliar, it',	'Pameran_200x300_L.png',	'2nd IT Exhibition 2018',	'2nd IT Exhibition 2018',	1,	1,	3503,	1,	'2018-01-19 09:35:50',	'2018-01-19 09:35:50',	'2026-11-24 19:00:32',	NULL),
(38,	'Yudisium Jurusan Teknologi Informasi Ke XV',	'yudisium-jurusan-teknologi-informasi-ke-xv',	'<p>Yudisium terakhir pada tahun ajaran 2017/2018 kemarin tanggal 19 Januari 2018 ini diikuti oleh 41 orang dengan rincian 20 yudisi dari Manajemen Informatika dan 21 yudisi dari Teknik Komputer.</p>\n<p>Acara dimulai dari masuknya barisan ketua jurusan, sekretaris jurusan, ketua program studi, dosen dan teknisi yang diiringi oleh lagu Bagimu Negeri. Demi khitmatnya acara pembacaan doa yang di bawakan oleh Bapak Agus Santoso A.Md. agar acara berjalan dengan lancar. dan dilanjutkan dengan menyanyikan Lagu Indonesia Raya dan Mars Polije.</p>\n<p>Selanjutnya, Sekretaris Jurusan Prawidya Destarianto, S.Kom. MT membaca Surat Keputusan Yudisium tentang mahasiswa yang namanya tertera pada putusan tersebut telah dinyatakan lulus dari Politeknik Negeri Jember.</p>\n<p>Acara dilanjutkan dengan pelepasan secara simbolis para yudisi oleh masing-masing program studi dan ketua jurusan Teknologi Informasi dengan maju satu persatu untuk diberikan sertifikat kelulusan mereka.</p>\n<p>Setelah pelepasan secara simbolis selesai sebagian yudisi mempersembahkan lagu untuk para hadirin semua, dan tak lupa terdapat beberapa kejutan yang telah disiapkan oleh panitia untuk memeriahkan acara dengan mendatangkan salah satu wali dari yudisi yang lagi bermain alat musik yaitu Baskoro yang terlalu fokus terhadap bermain alat musik sehingga tidak mengetahui ibunya berada didepannya, sehingga sedikit air mata bahagia yang mengalir pada acara ini.</p>\n<p>Setelah acara kejutan dari para yudisi, sekretaris jurusan kembali maju menuju podium untuk menyampaikan surat keputusan tentang Yudisi yang menerima predikat terbaik dari masing-masing program studi yaitu Nofry Chanda Pasedo dengan IPK 3,40 dari Manajemen Informatika dan Endah Cahyaning Tyas dengan IPK 3,43 dari Teknik Komputer.</p>\n<p>Akhir acara, dilakukan sesi foto bersama dosen, teknisi dan para yudisi untuk memberikan kenangan dan dokumentasi dari kegiatan Yudisium ke XV.</p>\n<p> </p>',	10,	'IMG_5962.JPG',	1,	0,	1,	'Yudisium Jurusan Teknologi Informasi Ke XV',	NULL,	NULL,	'IMG_5962.JPG',	'Yudisium Jurusan Teknologi Informasi Ke XV',	'Yudisium Jurusan Teknologi Informasi Ke XV',	1,	1,	4183,	1,	'2018-01-22 09:53:18',	'2018-01-22 09:53:18',	'2026-11-24 19:00:37',	NULL),
(39,	'Fieldtrip Jurusan Teknologi Informasi 2018 Goes To Bali',	'fieldtrip-jurusan-teknologi-informasi-2018-goes-to-bali',	'<p>Fieldtrip merupakan kegiatan mahasiswa tingkat akhir khususnya semester 5 Manajemen Informatika dan Teknik Komputer berkunjung ke lokasi industri untuk meninjau langsung seperti apa tempat kerja sebelum mahasiswa berangkat menuju kegiatan Praktek Kerja Lapang.</p>\n<p> </p>\n<p>Pada tahun ini kegiatan ini, tempat yang dikunjungi yaitu Bali TV, Bali Camp, Coca cola, Bali Creative Industry, dan Sinar Sosro.</p>\n<p> </p>\n<p>Kegiatan ini dilaksanakan selama 3 hari dari tanggal 22 s.d. 24 Januari 2018. Hari pertama digunakan untuk perjalanan dan wisata, hari kedua kunjungan Bali TV, Bali Camp, Coca cola. dan hari ke 3 kunjungan industry ke Bali Creative Industry dan Sinar Sosro.</p>\n<p> </p>',	9,	'IMG-20180123-WA0046.jpg',	1,	0,	1,	'Fieldtrip Jurusan Teknologi Informasi 2018 Goes To Bali',	NULL,	NULL,	'IMG-20180123-WA0046.jpg',	'Fieldtrip Jurusan Teknologi Informasi 2018 Goes To Bali',	'Fieldtrip Jurusan Teknologi Informasi 2018 Goes To Bali',	1,	1,	2874,	1,	'2018-01-30 13:25:32',	'2018-01-30 13:25:32',	'2026-11-25 00:16:02',	NULL),
(40,	'Perwakilan Jurusan Teknologi Informasi JUARA 1 Mahasiswa Berprestasi (MAWAPRES) POLIJE ',	'perwakilan-jurusan-teknologi-informasi-juara-1-mahasiswa-berprestasi-mawapres-polije',	'<p>Dalam seleksi Mahasiswa Berprestasi (MAWAPRES) ini pertama akan ada seleksi tingkat jurusan yang diwakili oleh 3-4 orang pada tiap program studi dan  disaring hingga satu orang untuk mewakili jurusan untuk seleksi tingkat POLIJE. Dari berbagai seleksi ketat dari jurusan akhirnya terpilih satu mahasiswa dari Prodi TKK Semester 4 yaitu Yuni Syafarinda.</p>\n<p> </p>\n<p>Perwakilan dari Jurusan ini harus mencari sebuah ide yang inovatif untuk karya ilmiah yang akan di persentasikan, akhirnya perwakilan dari JTI dengan banyak saran dari dosen pembimbing dan teman-temannya,  Yuni bekerjasama dengan Jurusan Produksi Pertanian membuat sebuah alat untuk monitoring ruangan kultur jaringan terhadap suhu, kelembapan dan intensitas cahaya dengan memanfaatkan website, wifi dan sensor dengan nilai tambah pengguna dapat mengontrol dan mengatur cahaya lampu yang akan diberikan.</p>\n<p><br><br>Tujuan dari pembuatan alat ini yaitu agar operator dapat secara realtime memonitoring kondisi ruangan kultur jaringan melalui website dan smartphone, sehingga operator secara tanggap dan cepat mengatasi jika terdapat kondisi yang tidak normal pada ruangan tersebut.</p>\n<p> </p>\n<p>Dalam penyeleksian POLIJE, perwakilan setiap jurusan harus melakukan persentasi atau demo karya tulisa yang dikerjakan serta terdapt sesi tanya jawab dari penguji dan peserta atas karya tulis yang diprsentasikan.</p>\n<p> </p>\n<p>Setelah seleksi yang panjang, akhirnya perwakilan JTI mendapatkan JUARA 1 dan berhak melanjutkan karya tulisnya ke tingkat nasional dengan saran alat yang dibuat bisa menyimpan data ke database secara realtime.</p>\n<p> </p>\n<p>Akhirnya kata Yuni mengucapkan terima kasih kepada Jurusan Teknologi Informasi, khususnya dosen pembimbing P. Beni Widiawan dan P. Yogiswara dan berbagai pihak yang telah membantu mensukseskan seleksi ini hingga Yuni berhak mendapatkan Juara 1 dan berhak mewakili POLIJE dalam PILMAPRES tingkat nasional.<br><br><strong>(djuliar)</strong></p>',	8,	'JUARA_1.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3765,	1,	'2018-03-14 10:18:50',	'2018-03-14 10:18:50',	'2026-11-24 19:01:22',	NULL),
(42,	'Peringatan Hari Kartini Polije,  JTI Meraih Juara',	'peringatan-hari-kartini-polije-jti-meraih-juara',	'<p>Dalam rangka memperingati Hari Kartini 2018, Polije mengadakan kegiatan lomba untuk para kartini / ibu-ibu dilingkungan Polije. yang telah terlaksana di GOR Perjuangan &singlequote;45 pada 26 April 2018. Adapun yang dilombakan yaitu Lomba Bakiak, Yel-yel Semangat, dan Bola Volley.</p>\n<p>Menindaklanjuti hal ini JTI turut memeriahkan acara tersebut dengan menurunkan personilnya untuk mengikuti lomba, pertama, bakiak diikuti oleh team yang berisi 3 orang, Yel-yel diikuti oleh team yang berisi 9 orang, dan Bola Volley diikuti oleh 4 orang.</p>\n<p>Akhirnya, Para Kartini JTI memenangkan Juara 3 Lomba Yel-yel Semangat Hari Kartini dan harapan 1 Lomba Bola Volley Tingkat Polije.</p>\n<p>Terima kasih Kartini JTI, Semoga semangat juang Ibu Kartini akan tetap ada di hati para kartini-kartini JTI.</p>',	8,	'WhatsApp_Image_2018-04-25_at_14_18_03.jpeg',	1,	0,	0,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3236,	1,	'2018-04-27 08:34:09',	'2018-04-27 08:34:09',	'2026-11-24 19:00:58',	NULL),
(43,	'Mahasiswa TI Kembali Berkarya dan Meraih Prestasi Dalam Kompetisi Robot Nasional Indonesia (KRI) 201',	'mahasiswa-ti-kembali-berkarya-dan-meraih-prestasi-dalam-kompetisi-robot-nasional-indonesia-kri-2018',	'<p>Jember - Tim Robotika IR64 Politeknik Negeri Jember telah mengikuti Kontes Robot Indonesia (KRI) 2018 yang diselenggarakan oleh Direktorat Kemahasiswaan, Direktorat Jenderal Pembelajaran dan Kemahasiswaan, Kementerian Riset, Teknologi, dan Pendidikan Tinggi di tingkat regional pada tanggal 1-3 Mei 2018 di Poiteknik Negeri Malang.</p>\n<p><br>Pada KRI 2018 Tim Robotika IR64 Politeknik Negeri Jember telah berpartisipasi aktif mengirimkan mahasiswanya untuk mengikuti ke5 (lima) divisi yaitu: Kontes Robot ABU Indonesia (KRAI), Kontes Robot Pemadam Api Indonesia (KRPAI), Kontes Robot Seni Tari Indonesia (KRSTI), Kontes Robot Sepak Bola Indonesia (KRSBI) Humanoid, dan Kontes Robot Sepak Bola Indonesia (KRSBI) Beroda.</p>\n<p>TIM Robotika kategori Kontes Robot ABU Indonesia (KRAI) 2018, yamg tergabung dalam TIM IRTONAS&singlequote;64 yang diprakarsai oleh Mahasiswa Jurusan Teknologi Informasi yaitu: Fahmi Ulin Nuha (TKK/2015), Hilman Zulfi (TKK/2015), Anton Prasetyo (TKK/2015), M. Nurkholis Ardiansyah (TKK/2017), dan David Sugianto (TIF/2016) berhasil meraih juara tiga dengan beberapa keunggulan desain robot yang telah dibuat. Keberhasilan ini tidak lepas dari peran dan bimbingan Bapak Beni Widiawan, S.ST, MT selaku pembina TIM Robotika Politeknik Negeri Jember.</p>\n<p>Melalui kompetesi yang cukup sengit dan perlawanan yang tidak mudah TIM IRTONAS&singlequote;64 yang melawan TIM RIVER dari ITS pada babak semi final harus terhenti karena waktu perlombaan yang hanya terpaut 0,05 sekian detik dengan TIM Lawan. Hal ini tidaklah menyiutkan semangat dan harapan mereka. Pertunjukan dan penampilan terbaik kembali dipertontonkan dengan sangat memukau untuk melawan Tim PENSAE dari Politeknik Elektronika Negeri Surabaya dalam perbutan juara 3. Tim PENSAE haruslah mengakui keunggulan dan kehebatan dari Tim Robot IRTONAS&singlequote;64</p>\n<p>Hal ini merupakan pencapaian luar biasa yang diraih oleh TIM Robotika Polije khususnya Tim Robot IRTONAS&singlequote;64 yang telah berhasil memberikan performa terbaiknya. Selamat dan Sukses kepada seluruh mahasiswa yang terlibat. Teruslah berkarya untuk membawa nama Jurusan Teknologi Informasi dan Almamater Politeknik Negeri Jember dalam KRI selanjutnya dan kompetisi Nasional lainnya.</p>\n<p> </p>',	8,	'logoKRI.png',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3564,	1,	'2018-05-05 11:20:29',	'2018-05-05 11:20:29',	'2026-11-24 19:00:41',	NULL),
(44,	'Jurusan Teknologi Informasi Berbagi Takjil Selama Bulan Ramadhan',	'jurusan-teknologi-informasi-berbagi-takjil-selama-bulan-ramadhan',	'<p>Jember - Bulan Ramadhan adalah bulan penuh berkah. Berbagai keutamaan bulan Ramadhan banyak disebutkan dalam hadist dan Al-Qur’an, salah satunya adalah keutamaan bersedekah atau berbagi dengan sesama dan memberi makan orang yang berpuasa di bulan suci ini. Seperti yang telah diriwayatkan dalam shahih Al-Bukhari dan Muslim, dari Ibnu Abbas radiyallahu anhuma : <em>“Nabi shallallahu alaihi wasallam adalah orang yang amat dermawan, dan beliau lebih dermawan pada bulan Ramadhan, saat beliau ditemui Jibril untuk membacakan padanya Al-Qur’an. Jibril menemui beliau setiap malam pada bulan Ramadhan, lalu membacakan padanya Al-Qur’an. Rasulullah shallallahu alaihi wasallam ketika ditemui jibril lebih dermawan dalam kebaikan daripada angin yang berhembus.”</em></p>\n<p>Hal ini juga dilakukan oleh Jurusan Teknologi Informasi yang telah mengadakan acara berbagi takjil dari awal puasa pada tanggal 16 Mei sampai menjelang libur lebaran pada tanggal 8 Juni. Jurusan Teknologi Informasi berbagi takjil gratis, khususnya untuk para mahasiswa Jurusan Teknologi Informasi yang telah pulang kuliah pada sore hari ataupun yang ingin berbuka bersama di Gedung Jurusan Teknologi Informasi. Pembagian takjil ini dapat terwujud dan terlaksana dengan baik  tidak lepas dari kerjasama seluruh warga Jurusan Teknologi Informasi baik dosen-dosen maupun mahasiswa setiap golongan dari masing-masing prodi.</p>\n<p>Apa yang diberikan dalam kegiatan berbagi takjil ini memanglah bukan apa-apa, namun yang terpenting adalah kebersamaan dan rasa saling berbagi. Berbagi kebahagiaan di bulan pernuh berkah ini adalah sebuah kebahagiaan yang bias terlihat dari senyum mahasiswa yang ikut serta dalam membagikan takjil pada saat itu. Selain itu kegiatan ini juga dapat lebih mempererat hubungan mahasiswa antara prodi yang satu dengan yang lain.</p>',	9,	'IMG_20180702_112255.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3246,	1,	'2018-05-17 11:38:02',	'2018-05-17 11:38:02',	'2026-11-24 18:59:43',	NULL),
(45,	'Ujian Akhir Semester Tahun Akademik 2017/2018 Dimulai Hari Ini',	'ujian-akhir-semester-tahun-akademik-2017-2018-dimulai-hari-ini',	'<p>Setelah libur panjang hari raya Idhul Fitri, Hari ini, 2 Juli 2018 mahasiswa mulai mengikuti rangkaian akhir dari perkuliahan yaitu Ujian Akhir Semester (UAS) yang diikuti oleh Mahasiswa Jurusan TI semester 2 dan 4 saja, karena semester 6 sudah selesai masa studinya diakhiri kegiatan Praktek Kerja Lapang (PKL).</p>\n<p> </p>\n<p><img src=\"IMG-20180702-WA00001.jpg\" width=\"640\"></p>\n<p> </p>\n<p>Cuaca sekitar Politeknik Negeri Jember pagi ini ditutupi kabut tebal dan udara dingin, sehingga pada jam 7 pagi mahasiswa belum datang, tapi selang 30 menit pada saat ujian akan dimulai, mahasiswa sudah ramai siap-siap menuju kelas masing-masing untuk mengikuti ujian.</p>\n<p> </p>\n<p><img title=\"\" src=\"IMG_20180702_080523.jpg\" width=\"640\"></p>\n<p><img title=\"\" src=\"IMG_20180702_080604.jpg\" alt=\"\" width=\"640\"></p>\n<p> </p>\n<p>Ujian akhir semester diawal dengan Prodi Manajemen Informatika semester 4 dengan Agro Informatika dan Tekni Informatika semester 2 untuk Ujian Matematika Diskrit.</p>\n<p> </p>\n<p><img title=\"\" src=\"IMG_20180702_105520.jpg\" alt=\"\" width=\"640\"></p>\n<p> </p>\n<p>Unit Pelayanan Kelas Juga Telah Siap Berjaga untuk menyerahkan soal pada masing-masing pengawas ujian.</p>\n<p>Selamat Mengerjakan &amp; Sukses Ujian Akhir Semester Tahun Akademik 2017/2018</p>\n<p> </p>\n<p><img src=\"eid-mubarak-text-messages.jpg\" alt=\"\"></p>\n<p> </p>\n<p>Dan tak lupa pula Admin Website Jurusan Teknologi Informasi dan Segenap Civitas Akademika Jurusan Teknologi Informasi Mengucapkan Taqabballahu Minna Wa Minkum Wa Ja&singlequote;alana Minal &singlequote;Aidzin Wal Faizin Mohon Maaf Lahir dan Batin.</p>\n<p> </p>\n<p><strong>(Djuliar)</strong></p>',	12,	'UAS.jpg',	1,	0,	1,	'Setelah libur panjang hari raya Idhul Fitri, Hari ini, 2 Juli 2018 mahasiswa mulai mengikuti rangkaian akhir dari perkuliahan yaitu Ujian Akhir Semester (UAS)',	'djuliar',	'jti, uas, polije, djuliar',	'UAS.jpg',	'Ujian Akhir Semester Tahun Akademik 2017/2018 Dimulai Hari Ini',	'Setelah libur panjang hari raya Idhul Fitri, Hari ini, 2 Juli 2018 mahasiswa mulai mengikuti rangkaian akhir dari perkuliahan yaitu Ujian Akhir Semester (UAS)',	1,	1,	7003,	1,	'2018-07-02 12:07:37',	'2018-07-02 12:07:37',	'2026-11-24 18:59:30',	NULL),
(46,	'Menengok Inovasi Baru Mahasiswa Polije Bikin Aplikasi Buku Sukses',	'menengok-inovasi-baru-mahasiswa-polije-bikin-aplikasi-buku-sukses',	'<div class=\"row\" style=\"margin-left: 0px; margin-right: 0px;\">\n<div class=\" deduktif-paragraph text-justify\">\n<p class=\"first-paragraph-bottom-zero\">novasi teknologi sudah menjadi kewajiban untuk memberikan kemudahan bagi masyarakat. Sayangnya, tak semua inovasi yang dibuat mahasiswa bisa diterapkan. Hanya sebagian saja, seperti aplikasi Buku Sukses ini.</p>\n<p class=\"first-paragraph-bottom-zero\"> </p>\n</div>\n</div>\n<div class=\"text-justify\" style=\"clear: both;\">\n<p>Awalnya hanya buku biasa yang berisi cara menilai karakter anak. Mulai dari karakter keagamaan, kecerdasan, sosial, dan lainnya. Namanya Buku Sukses, buku yang dipegang siswa untuk menilai sendiri kesehariannya. </p>\n<p> </p>\n</div>\n<div class=\"text-justify\">\n<p>Misal, jam berapa salat subuh? bagaimana perasaan hari ini? Apakah sudah hormat kepada orang tua? Dan lainnya. Ada lima jawaban untuk pertanyaan tersebut, yakni A hingga D. Setiap hari, orang tua mendampingi anaknya menjawab pertanyaan tersebut. </p>\n<p> </p>\n</div>\n<div class=\"text-justify\">\n<p>Jawaban itu menjadi penilaian kepribadian seorang anak melalui ilmu psikologi. Penerapan Buku Sukses itu dilakukan di SDN Dabasah 1 Bondowoso. “Awalnya hanya manual, menuliskannya pada kertas,” kata Misbahul Hasan, mahasiswa Teknik Informatika Politeknik Negeri Jember.</p>\n<p> </p>\n<p>Penilaian yang konvensional itu menggerakkan Misbah dan beberapa temannya untuk mempermudah. Yakni membuat aplikasi penilaian kepribadian anak, sehingga tak perlu lagi menuliskannya di atas kertas, namun bisa menjawab melalui komputer atau gawai. </p>\n<p> </p>\n<p>Selain Misbah, ada juga Enggal Deny, Fikri Robiyaturrohman, A Syamsul Arifin, dan M Hilmy. Lima mahasiswa itu mencoba membuat inovasi yang langsung bisa diterapkan. Selama dua tahun, mereka berusaha agar bisa membuat aplikasi Buku Sukses untuk menilai kepribadian pelajar. </p>\n<p> </p>\n<p>Misbah berupaya mengembangkan Buku Sukses yang digagas oleh Teddy Hamzah melalui super student di Bondowoso. “Saya pernah menjadi super student, ada tumpukan kertas penilaian,” akunya. </p>\n<p> </p>\n<p>Tentu saja, kertas yang digunakan itu kurang efisien dan boros. Tak heran, Misbah terus berupaya mengembangkan aplikasi itu untuk mempermudah proses manajamen program Buku Sukses dalam menentukan kepribadian siswa. Diterapkan di SDN Dabasah 1 Bondowoso karena pemahaman pihak sekolah dan orang tua siswa juga sejalan dengan program Buku Sukses. </p>\n<p> </p>\n<p>Inovasi program Buku Sukses itu memberikan  form yang harus diisi secara digital setiap hari tentang aktivitas siswa. Baik di sekolah maupun di rumah.  Form pertanyaan yang harus diisi terdiri atas empat kategori, yakni kegiatan religi, kegiatan di rumah, kegiatan di sekolah, dan cerita tentang perasaan hari ini </p>\n<p> </p>\n<p>Setelah form diisi, akan dikumpulkan pada  Teddy Hamzah, psikolog yang menjadi penanggung jawab utama program Buku Sukses sekaligus mentor. Dari jawaban itulah, Teddy bisa menilai kepribadian anak. “Aplikasi yang kami buat awalnya tugas mata kuliah Sistem Informasi,” ujarnya. </p>\n<p> </p>\n<p>Misbah bersama Dyah Ayu Dwijayanti dan Ully Nuhanatika, kemudian terus dikembangkan menjadi program yang bisa dimanfaatkan. Bahkan, sekarang terus dikembangkan agar bisa diterapkan di semua sekolah dasar. </p>\n<p> </p>\n<p>Misbah bersama empat temannya sedang mengembangkan sistem pakar agar aplikasi tersebut bisa langsung menilai kepribadian siswa. Tanpa harus dilakukan secara manual dengan melihat nilai jawaban. “Secara otomatis ketika mengisi nilai, kepribadian anak bisa dijawab komputer,” ungkapnya. </p>\n<p> </p>\n<p>Inovasi teknologi itu hanya salah satu hasil yang dilakukan oleh mahasiswa Politeknik Negeri Jember. Sebab, setiap mahasiswa harus membuat tugas inovasi setiap semester. “Sebelumnya, saya juga membuat aplikasi Grow Up,” ucapnya. </p>\n<p> </p>\n<p>Yakni aplikasi konsultasi para petani pada pakar melalui sistem daring (online).  Petani bisa bertanya tentang masalah yang dialami dengan cara menghubungkan petani agar bisa sharing dengan ahli pertanian. Bahkan, aplikasi yang dibuatnya mewakili Indonesia untuk dipresentasikan di Singapura dan sempat membuat investor asing tertarik. </p>\n<p> </p>\n<p>Misbah pun mendapat kesempatan bertukar pendapat tentang pengembangan inovasi teknologi di Singapura. Selain itu, dia juga mengikuti pertukaran belajar ke Korea Selatan, negara terbaik di bidang inovasi teknologi. </p>\n<p> </p>\n<p>Diakuinya, Indonesia kalah dari sisi penerapan inovasi yang sudah dilakukan. Mereka hanya melakukan inovasi, namun tidak langsung diterapkan. Berbeda dengan Korsel, aplikasi yang dibuat langsung diterapkan di masyarakat. “Kita kalahnya dari sisi penerapan, kalau SDM dan inovasinya tidak kalah,” jelas mahasiswa asal Bondowoso tersebut. </p>\n<p> </p>\n<p>Ketua Jurusan Teknik Informatika Polije Wahyu Kurnia Dewanto mengarahkan para mahasiswanya agar membuat produk aplikasi yang bisa diterapkan langsung di masyarakat. Meskipun tugas kampus, namun bisa digunakan. “Itu kami terapkan pada mahasiswa semester IV,” ucapnya. </p>\n<p> </p>\n<p>Setiap prodi di jurusan tersebut, mulai dari Manajemen Informatika, Teknik Komputer, dan Teknologi Informatika, mampu membuat 40 inovasi setiap semester. Semua itu ada yang bisa dikembangkan menjadi program yang aplikatif. “Namun, sebagian juga ada yang belum bisa digunakan,” tambahnya. </p>\n<p> </p>\n<p>Caranya, lanjut dia, mahasiswa yang hendak membuat inovasi teknologi harus melakukan survei dahulu, sesuai dengan kebutuhan pengguna. Misal, membuat aplikasi untuk usaha jasa boga (catering) atau jasa penatu (laundry), mahasiswa harus melihat kebutuhan pelaku usaha. “Justru ide untuk berinovasi itu bisa datang dari warga yang membutuhkan,” ucapnya. </p>\n<p> </p>\n<p>Bagi pria yang akrab disapa Wahyu tersebut, inovasi teknologi sudah menjadi kewajiban. Apalagi, sudah memasuki era industri 4.0. “Tantangan sekarang harus inovatif agar tidak tertinggal,” ujarnya. </p>\n<p> </p>\n<p>Polije, lanjut dia, sudah memiliki berbagai inovasi teknologi yang dikembangkan. Seperti tongkat orang buta yang dibuat dengan teknologi mampu melihat lubang atau barang di depannya. Ketika ada lubang, maka akan berbunyi. Kemudian, teknologi untuk mendeteksi telur busuk dan lainnya. “Hanya saja, masih belum layak jual, belum dikemas dengan baik,” papar Wahyu.</p>\n<p> </p>\n<p>Inovasi tersebut perlu didukung dengan kemasan yang menarik agar bisa dimanfaatkan masyarakat. Untuk itu, perlu peningkatan proses, tidak hanya membuat, tetapi juga produksi. “Dari hulu ke hilir bisa dilakukan, namun butuh proses pengembangan ke sana,” imbuhnya.</p>\n<p> </p>\n<p>Selain itu, untuk mengejar ketertinggalan di bidang inovasi teknologi. Para pelajar tingkat SD hingga SMA harus dikenalkan tentang teknologi. Siswa perlu mendapat informasi tentang perkembangan teknologi, lalu diajari untuk berinovasi. </p>\n<p> </p>\n<p>Artikel di Kutip dari Jawa Pos Kamis, 05 Jul 2018 editor : Dzikri Abdi Setia</p>\n</div>\n<p><strong><a href=\"https://radar.jawapos.com/radarjember/read/2018/07/05/85467/menengok-inovasi-baru-mahasiswa-polije-bikin-aplikasi-buku-sukses\">Artikel Asli</a></strong></p>',	8,	'menengok-inovasi-baru-mahasiswa-polije-bikin-aplikasi-buku-sukses_m_85467.jpeg',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3766,	1,	'2018-07-09 18:49:48',	'2018-07-09 18:49:48',	'2026-11-24 18:59:10',	NULL),
(47,	'Pelatihan Sertifikasi Kompetensi Mahasiswa Bidik Misi 2018',	'pelatihan-sertifikasi-kompetensi-mahasiswa-bidik-misi-2018',	'<p>Jurusan Teknologi Informasi pada 16-19 Juli 2018 berkesempatan untuk melaksanakan Pelatihan Sertifikasi Kompetensi Mahasiswa Bidik Misi Pendidikan Tinggi Vokasi 2018 yang telah dibuka secara simbolis oleh Direktur Polije Dr. Ir. Nanang Dwi Wahyono, MM di Gedung Serbaguna Soetrisno Widjaja.</p>\n<p> </p>\n<p>Skema pelatihannya yaitu Sertifikasi Penginstalasian Infrastruktur Jaringan Komputer Lokal dan Sertifikasi Perancangan Pengembangan Mobile API.</p>\n<p> </p>\n<p>Kegiatan ini dilaksanakan oleh Lembaga Sertifikasi Profesi Pihak Ke 1 yang di percayakan pada Politeknik Negeri Jember yang telah mendapatkan lisensi dari Badan Nasional Sertifilkasi Profesi (BNSP) pada 17 Mei 2016.</p>\n<p> </p>\n<p>Pelatihan ini diikuti oleh 6 Politeknik yaitu Politeknik Negeri Jember, Politkenik Negeri Fakfak Papua Barat, Politeknik Negeri Madiun, Politeknik Negeri Bengkalis Riau, Politeknik Tanah Laut Kalimantan Selatan, Politeknik Negeri Banyuwangi.</p>\n<p> </p>\n<p>Sedangkan pada tanggal 20-21 Juli 2018 kegiatan ini akan diakhiri dengan Ujian Sertifikasi Kompetensi dari pelatihan yang telah dijalani selama empat hari itu.</p>\n<p><strong>(djuliar)</strong></p>',	9,	'headline.jpg',	1,	0,	1,	'Pelatihan Sertifikasi Kompetensi Mahasiswa Bidik Misi 2018',	'djuliar',	'Pelatihan Sertifikasi Kompetensi Mahasiswa Bidik Misi 2018',	'headline.jpg',	'Pelatihan Sertifikasi Kompetensi Mahasiswa Bidik Misi 2018',	'Pelatihan Sertifikasi Kompetensi Mahasiswa Bidik Misi 2018',	1,	1,	2727,	1,	'2018-07-18 11:16:07',	'2018-07-18 11:16:07',	'2026-11-24 18:58:48',	NULL),
(48,	'Pakaian Adat Unit Jurusan Teknologi Informasi pada Dirgahayu Kemerdakaan Republik Indonesia 2018',	'pakaian-adat-unit-jurusan-teknologi-informasi-pada-dirgahayu-kemerdakaan-republik-indonesia-2018',	'<p>Pada peringatan hari Kemerdekaan Republik Indonesia pada 17 Agustus 2018, Politeknik memberikan kebijakan setiap unit Jurusan dan Administrasi diwajibkan sebagian untuk memakai pakaian adat Indonesia.</p>\n<p>untuk Jurusan Teknologi Informasi diwakilkan oleh Ketua Jurusan yang memakai pakaian adat dari Bengkulu,</p>\n<p>Ibu Maya memakai pakaian adat dari Jawa Barat, Ibu Betty memakai pakaian adat dari Bali,</p>\n<p>Ibu Vani memakai pakaian adat dari Kalimantan Selatan, dan Ibu Mery memakai pakaian adat dari Nusa Tenggara Timur.</p>\n<p>Tak Lupa Pula, Bapak Direktur beserta Wakil Direktur dan Kepala Bagian unit juga memakai pakaian adat dan dilakukan pawai sebelum acara Kemerdekaan 17 Agustus dimulai secara khidmat.</p>\n<p>[<strong>djuliar</strong>] </p>\n<blockquote class=\"instagram-media\" style=\"background: #FFF; border: 0; border-radius: 3px; box-shadow: 0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width: 540px; min-width: 326px; padding: 0; width: calc(100% - 2px);\" data-instgrm-captioned=\"\" data-instgrm-permalink=\"https://www.instagram.com/p/Bms3e19gdDx/?utm_source=ig_embed\" data-instgrm-version=\"9\">\n<div style=\"padding: 8px;\">\n<div style=\"background: #F8F8F8; line-height: 0; margin-top: 40px; padding: 45.614035087719294% 0; text-align: center; width: 100%;\"> </div>\n<p style=\"margin: 8px 0 0 0; padding: 0 4px;\"><a style=\"color: #000; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: normal; line-height: 17px; text-decoration: none; word-wrap: break-word;\" title=\"\" href=\"https://www.instagram.com/p/Bms3e19gdDx/?utm_source=ig_embed\" target=\"_blank\">Pakaian Adat Indonesia Unit Jurusan Teknologi Informasi pada Peringatan Dirgahayu Kemerdekaan Republik Indonesi Ke-73 17 Agustus 2018 . . . . #polije #polijehits #jti #jtipolije #poltek #poltekjember #politeknik #politekniknegerijember #kampus #kampusrusa #universitas #mahasiswa #mahasiswajember #mahasiswahits #mif #tkk #tif #manajemeninformatika #teknikkomputer #teknikinformatima #jember #jemberhits #indonesia #hots #hits</a></p>\n<p style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; line-height: 17px; margin-bottom: 0; margin-top: 8px; overflow: hidden; padding: 8px 0 7px; text-align: center; text-overflow: ellipsis; white-space: nowrap;\">A post shared by <a style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: normal; line-height: 17px;\" href=\"https://www.instagram.com/jtipolije/?utm_source=ig_embed\" target=\"_blank\"> Jurusan Teknologi Informasi</a> (@jtipolije) on <time style=\"font-family: Arial,sans-serif; font-size: 14px; line-height: 17px;\" datetime=\"2018-08-20T12:40:37+00:00\">Aug 20, 2018 at 5:40am PDT</time></p>\n</div>\n</blockquote>',	10,	'WhatsApp_Image_2018-08-17_at_20_02_30.jpg',	1,	0,	1,	'Pakaian Adat Unit Jurusan Teknologi Informasi pada Dirgahayu Kemerdakaan Republik Indonesia 2018',	'djuliar',	'kemerdekaan, dirgahayu, polije, jti',	'WhatsApp_Image_2018-08-17_at_20_02_30.jpg',	'Pakaian Adat Unit Jurusan Teknologi Informasi pada Dirgahayu Kemerdakaan Republik Indonesia 2018',	'Pakaian Adat Unit Jurusan Teknologi Informasi pada Dirgahayu Kemerdakaan Republik Indonesia 2018',	1,	1,	3682,	1,	'2018-08-21 13:21:47',	'2018-08-21 13:21:47',	'2026-11-25 08:39:59',	NULL),
(49,	'Pengenalan Kehidupan Kampus Bagi Mahasiswa Baru Jurusan Teknologi Informasi',	'pengenalan-kehidupan-kampus-bagi-mahasiswa-baru-jurusan-teknologi-informasi',	'<p>PKKMB bertujuan untuk memperkenalkan dan mempersiapkan mahasiswa baru dalam proses transisi menjadi mahasiswa, di dalamnya diisi dengan berbagai kegiatan yang terkait dengan penanaman wawasan kebangsaan/cinta tanah air/bela negara dan mempelajari berbagai hal yang berkaitan dengan kegiatan akademik, kegiatan kemahasiswaan serta kebijakan kampus sehingga dapat menjadi bekal untuk mendukung keberhasilan studinya di perguruan tinggi.</p>\n<p>Jumat, 31 Agustus 2018, merupakan hari ke-5 bagi mahasiswa baru dalam PKKMB, pada hari itu merupakan bagian untuk pihak jurusan khususnya Jurusan Teknologi Informasi untuk Mahasiswa Baru bisa berkenalan dan bertemu dengan lingkungan Jurusan TI.</p>\n<p>Mahasiswa baru Jurusan Teknologi Informasi berkumpul di Gelanggang Olahraga (GOR) Perjuangan &singlequote;45, dan turut hadir segenap dosep dan staf karyawan dari Jurusan Teknologi Informasi.</p>\n<p>Kegiatan dipimpin langsung oleh sekretaris jurusan Prawidya Destarianto, S.Kom, MT. diawali dengan senam bersama segenap dosen dan karyawan beserta mahasiswa baru peserta PKKMB.</p>\n<p>Kemudian dilanjutkan dengan pengenalan dan deskripsi umum tentang Jurusan Teknologi Informasi dari Visi Misi, Program Studi, Fasislitas, Data Dosen, Administrasi dan Teknisi lingkungan Jurusan Teknologi Informasi. Bagi peserta PKKMB yang aktif dalam kegiatan ini diberi sebuah bingkisan oleh P. Rian.</p>\n<p>Pada akhir kegiatan dilakukan foto bersama dosen dan staf keryawan Jurusan Teknologi Informasi dan acara dilanjutkan di pimpin oleh himpunan Jurusan TI (HMJTI)</p>\n<p><strong>[djuliar]</strong></p>\n<p><iframe src=\"https://www.youtube.com/embed/AFvOSGkKR1g\" width=\"100%\" height=\"428\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe></p>',	9,	'IMG_0280.JPG',	1,	0,	1,	'Pengenalan Kehidupan Kampus Bagi Mahasiswa Baru Jurusan Teknologi Informasi',	'djuliar',	'pkkmb, djuliar, jti, polije',	'IMG_0280.JPG',	'Pengenalan Kehidupan Kampus Bagi Mahasiswa Baru Jurusan Teknologi Informasi',	'Pengenalan Kehidupan Kampus Bagi Mahasiswa Baru Jurusan Teknologi Informasi',	1,	1,	4048,	1,	'2018-09-04 12:30:43',	'2018-09-04 12:30:43',	'2026-11-25 02:54:59',	NULL),
(50,	'Focus Group Discussion oleh Profesor Pitoyo Peter Hartono dari Chukyo University',	'focus-group-discussion-oleh-profesor-pitoyo-peter-hartono-dari-chukyo-university',	'<p>Prof. Pitoyo Peter Hartono, lahir di Surabaya tahun 1969, saat ini berdomisili di Hakodate. beliau merupakan lulusan S-3 Waseda University.</p>\n<p>Bersama beliau Dosen Jurusan Teknologi Informasi berkesempatan melakukan kegiatan FGD (Focus Group Discussion) pada Jumat, 14 September 2018 dan Stadium General bersama mahasiswa JTI.</p>\n<p>Acara FGD dimulai tepat Jam 8 pagi yang tak luput pula dihadiri oleh Wakil Direktur Bidang Kemahasiswaan M. Munih Dian Widianta yang juga sebagai dosen JTI dan acara diawali sambutan oleh Ketua Jurusan Teknologi Informasi.</p>\n<p>Kegiatan harus terhenti sejenak untuk melaksanakan sholat Jumat, dan dilanjutkan kembali pada jam 13.00 hingga 16.00 WIB.</p>\n<p>Dalam kegiatan ini Prof. Pitoyo Peter Hartono menjelaskan berbagai cara dan metode dalam membuat sebuah penelitian dan paper yang bertaraf international. Dengan adanya kegiatan ini beliau berharap sebagai dosen bukan hanya sebagai pengajar mata kuliah tetapi juga meluangkan sebagian waktunya untuk melakukan penelitian dibidangnya.</p>\n<p>pada akhir kegiatan berkesempatan melakukan foto sesi bersama dengan Prof. Pitoyo Peter Hartono beserta seluruh dosen Jurusan Teknologi Informasi.</p>\n<p>Pada kegiatan hari berikutnya, Prof. Pitoyo Peter Hartono juga memberikan <strong>Stadium General</strong> yang bertempat di GOR Perjuangan &singlequote;45 kepada Mahasiswa Jurusan Teknologi Informasi tentang <em><strong>\"Recent Topics on Computational Intellegence and Robotic\"</strong></em> sebagaimana riset yang beliau kerjakan saat ini.</p>',	9,	'IMG20180914162135.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3237,	1,	'2018-09-19 10:49:00',	'2018-09-19 10:49:00',	'2026-11-24 20:11:43',	NULL),
(51,	'Yudisium Jurusan Teknologi Informasi Ke XVI',	'yudisium-jurusan-teknologi-informasi-ke-xvi',	'<p>Dengan puji syukur ke hadirat Tuhan YME, Yudisium ke XVI sukses diselenggarakan dengan lancar. Kemarin tepat tanggal 25 September 2018 Jam 7 pagi Yudisium ke XVI yang diikuti oleh 79 orang yudisi dengan rincian 54 yudisi Program Studi Manajemen Informatika dan 25 yudisi Program Studi Teknik Komputer.</p>\n<p>Pra-acara dimulai dengan pemutaran video slideshow kenangan para yudisi selama mereka menempuh lika liku kehidupan kampus. Para yudisi dengan fokus melihat satu persatu foto kenangan dengan berbagai ekspresi dan emosi masing-masing.</p>\n<p>Acara resmi dimulai dari masuknya barisan ketua jurusan, sekretaris jurusan, ketua program studi, dosen dan teknisi yang diiringi oleh lagu Bagimu Negeri. Demi khitmatnya acara pembacaan doa yang di bawakan oleh Bapak Novianto Hadi Raharjo A.Md. agar acara berjalan dengan lancar dan dilanjutkan dengan menyanyikan Lagu Indonesia Raya dan Mars Polije.</p>\n<p>Selanjutnya, Sekretaris Jurusan Prawidya Destarianto, S.Kom. MT membaca Surat Keputusan Yudisium tentang mahasiswa yang namanya tertera pada putusan tersebut telah dinyatakan lulus dari Politeknik Negeri Jember.</p>\n<p>Acara dilanjutkan dengan pelepasan secara simbolis para yudisi oleh masing-masing program studi dan ketua jurusan Teknologi Informasi dengan maju satu persatu untuk diberikan sertifikat kelulusan mereka.</p>\n<p>Setelah pelepasan para yudisi atas kelulusannya, perwakilan yudisi mempersembahkan sebuah lagu khusus untuk dosen yang hadir kala itu, diantara yudisi juga memberikan bunga kepada dosen sebagai bukti rasa terima kasih atas segala ilmu yang telah diberikan selama ini.</p>\n<p>Sekretaris jurusan kembali maju menuju podium untuk menyampaikan surat keputusan tentang Yudisi yang menerima predikat terbaik dari masing-masing program studi yaitu <strong>Imarotur Rizqiyah</strong> dengan IPK <strong>3,75</strong> dari Manajemen Informatika dan <strong>Ahmad Waris Al Havids</strong> dengan IPK 3,81 dari Teknik Komputer.</p>\n<p>Akhir acara, dilakukan sesi foto bersama dosen, teknisi dan para yudisi untuk memberikan kenangan dan dokumentasi dari kegiatan Yudisium ke XVI dan dilanjutkan Ramah Tamah.</p>\n<p>Acara ini sukses terselenggara atas arahan dengan sabar dari Ketua Panitia Baru Ibu Bety Etikasari, S.Pd, M.Pd beliau menyampaikan banyak terima kasih atas segenap panitia dan segenap yang terlibat dalam acara tersebut, acara tidak akan terselenggara dengan lancar tanpa kekompakan panitia sekalian.</p>\n<p><strong>(Djuliar)</strong></p>\n<div class=\"row\">\n<div class=\"col-md-6\">\n<blockquote class=\"instagram-media\" style=\"background: #FFF; border: 0; border-radius: 3px; box-shadow: 0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width: 540px; min-width: 326px; padding: 0; width: calc(100% - 2px);\" data-instgrm-captioned=\"\" data-instgrm-permalink=\"https://www.instagram.com/p/BoMDm05AvZM/?utm_source=ig_embed&amp;utm_medium=loading\" data-instgrm-version=\"12\">\n<div style=\"padding: 16px;\">\n<div style=\"display: flex; flex-direction: row; align-items: center;\"> </div>\n<div style=\"padding: 19% 0;\"> </div>\n<div style=\"display: block; height: 50px; margin: 0 auto 12px; width: 50px;\"> </div>\n<div style=\"padding-top: 8px;\">\n<div style=\"color: #3897f0; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: 550; line-height: 18px;\">View this post on Instagram</div>\n</div>\n<p style=\"margin: 8px 0 0 0; padding: 0 4px;\"><a style=\"color: #000; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: normal; line-height: 17px; text-decoration: none; word-wrap: break-word;\" href=\"https://www.instagram.com/p/BoMDm05AvZM/?utm_source=ig_embed&amp;utm_medium=loading\" target=\"_blank\">YUDISIUM KE XVI JURUSAN TEKNOLOGI INFORMASI POLITEKNIK NEGERI JEMBER 25 SEPTEMBER 2018 . . PART - 1 . . #polije #polijehits #jti #jtipolije #poltek #poltekjember #politeknik #politekniknegerijember #kampus #kampusrusa #universitas #mahasiswa #mahasiswajember #mahasiswahits #mif #tkk #tif #manajemeninformatika #teknikkomputer #teknikinformatima #jember #jemberhits #jemberbanget #indonesia #hots #hits</a></p>\n<p style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; line-height: 17px; margin-bottom: 0; margin-top: 8px; overflow: hidden; padding: 8px 0 7px; text-align: center; text-overflow: ellipsis; white-space: nowrap;\">A post shared by <a style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: normal; line-height: 17px;\" href=\"https://www.instagram.com/jtipolije/?utm_source=ig_embed&amp;utm_medium=loading\" target=\"_blank\"> Jurusan Teknologi Informasi</a> (@jtipolije) on <time style=\"font-family: Arial,sans-serif; font-size: 14px; line-height: 17px;\" datetime=\"2018-09-26T11:54:25+00:00\">Sep 26, 2018 at 4:54am PDT</time></p>\n</div>\n</blockquote>\n</div>\n<div class=\"col-md-6\">\n<blockquote class=\"instagram-media\" style=\"background: #FFF; border: 0; border-radius: 3px; box-shadow: 0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width: 540px; min-width: 326px; padding: 0; width: calc(100% - 2px);\" data-instgrm-captioned=\"\" data-instgrm-permalink=\"https://www.instagram.com/p/BoMEiaugRFN/?utm_source=ig_embed&amp;utm_medium=loading\" data-instgrm-version=\"12\">\n<div style=\"padding: 16px;\">\n<div style=\"display: flex; flex-direction: row; align-items: center;\"> </div>\n<div style=\"padding: 19% 0;\"> </div>\n<div style=\"display: block; height: 50px; margin: 0 auto 12px; width: 50px;\"> </div>\n<div style=\"padding-top: 8px;\">\n<div style=\"color: #3897f0; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: 550; line-height: 18px;\">View this post on Instagram</div>\n</div>\n<p style=\"margin: 8px 0 0 0; padding: 0 4px;\"><a style=\"color: #000; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: normal; line-height: 17px; text-decoration: none; word-wrap: break-word;\" title=\"\" href=\"https://www.instagram.com/p/BoMEiaugRFN/?utm_source=ig_embed&amp;utm_medium=loading\" target=\"_blank\">YUDISIUM KE XVI JURUSAN TEKNOLOGI INFORMASI POLITEKNIK NEGERI JEMBER 25 SEPTEMBER 2018 . . PART - 2 . . #polije #polijehits #jti #jtipolije #poltek #poltekjember #politeknik #politekniknegerijember #kampus #kampusrusa #universitas #mahasiswa #mahasiswajember #mahasiswahits #mif #tkk #tif #manajemeninformatika #teknikkomputer #teknikinformatima #jember #jemberhits #jemberbanget #indonesia #hots #hits</a></p>\n<p style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; line-height: 17px; margin-bottom: 0; margin-top: 8px; overflow: hidden; padding: 8px 0 7px; text-align: center; text-overflow: ellipsis; white-space: nowrap;\">A post shared by <a style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: normal; line-height: 17px;\" href=\"https://www.instagram.com/jtipolije/?utm_source=ig_embed&amp;utm_medium=loading\" target=\"_blank\"> Jurusan Teknologi Informasi</a> (@jtipolije) on <time style=\"font-family: Arial,sans-serif; font-size: 14px; line-height: 17px;\" datetime=\"2018-09-26T12:02:33+00:00\">Sep 26, 2018 at 5:02am PDT</time></p>\n</div>\n</blockquote>\n</div>\n</div>',	10,	'headline_yudisium_xvi.jpg',	1,	0,	1,	'Kemarin tepat tanggal 25 September 2018 Jam 7 pagi Yudisium ke XVI yang diikuti oleh 79 orang yudisi dengan rincian 54 yudisi Program Studi Manajemen Informatik',	'djuliar',	'djuliar, jti, polije, yudisium',	'headline_yudisium_xvi.jpg',	'Yudisium Jurusan Teknologi Informasi Ke XVI',	'Kemarin tepat tanggal 25 September 2018 Jam 7 pagi Yudisium ke XVI yang diikuti oleh 79 orang yudisi dengan rincian 54 yudisi Program Studi Manajemen Informatika dan 25 yudisi Program Studi Teknik Komputer.',	1,	1,	3881,	1,	'2018-09-26 19:23:14',	'2018-09-26 19:23:14',	'2026-11-24 18:58:53',	NULL),
(52,	'Oracle Academy Student Day',	'oracle-academy-student-day',	'<p>Kami mengundang siswa/Mahasiswa Oracle Academy untuk bergabung dengan kami guna mendapatkan kesempatan untuk mempelajari tentang topik-topik yang sedang tren saat ini — termasuk Cloud, Big Data, Machine Learning, dan Blockchain — dan menjelajahi sumber daya karir yang tersedia dalam bidang teknologi. Oracle Academy Virtual Student Day, yang dibuat untuk anggota siswa/mahasiswa Oracle Academy, menawarkan webinar yang dibuat dan disajikan oleh karyawan Oracle, yang akan berbagi pengetahuan mereka tentang tren teknologi terbaru serta perjalanan karir pribadi mereka dalam industri TI.</p>\n<p>DETAIL ACARA</p>\n<ul>\n<li>Kamis, 27 September  2018 10:30am – 14:30 WIB</li>\n<li>Virtual student day  akan berlangsung secara ONLINE melalui tautan URL unik</li>\n<li>Catatan: Koneksi internet, computer/laptop/telepon genggam, headset audio diperlukan.</li>\n</ul>\n<p>SIAPA YANG HARUS MENGIKUTI ACARA INI?</p>\n<ul>\n<li>Siswa SMK dan Mahasiswa yang mempelajari Ilmu Komputer atau yang belum memilih jurusan</li>\n<li>Para siswa/mahasiswa yang ingin tahu tentang ilmu komputer dan teknologi</li>\n</ul>\n<p>APA YANG AKAN DIPELAJARI SISWA/MAHASISWA?</p>\n<ul>\n<li>Keterampilan yang dibutuhkan, jalur pembelajaran yang dapat diakses, perjalanan karir yang diambil oleh karyawan saat ini yang ada di industri, dan sertifikasi yang tersedia untuk membantu siswa/mahasiswa siap untuk mencapai kesiapan karir</li>\n<li>Ikhtisar Cloud, Big Data, Machine Learning, Blockchain, dan lainnya</li>\n<li>Informasi tentang bidang IT dan tren teknologi terkini</li>\n</ul>\n<p>MENGAPA SISWA/MAHASISWA HARUS MENGIKUTI ACARA INI?</p>\n<ul>\n<li>Terinspirasi untuk mencapai impian mereka</li>\n<li>Dapatkan Sertifikat Partisipasi untuk setiap webinar lengkap yang dilihat/diikuti</li>\n</ul>\n<p>Selengkapnya pada lampiran berikut</p>\n<div class=\"alert alert-icon alert-primary\" style=\"padding-left: 2rem;\">\n<h5><strong> Lampiran</strong></h5>\n<a href=\"http://jti.polije.ac.id/assets/pdf/Event Agenda (Update 17Sep18).pdf\" target=\"_blank\">Event Agenda (Update 17Sep18).pdf</a><br><a href=\"http://jti.polije.ac.id/assets/pdf/Flyer OAVSD 27 Sept 18 (Upd. 23Aug18).pdf\" target=\"_blank\">Flyer OAVSD 27 Sept 18 (Upd. 23Aug18).pdf</a></div>',	14,	'oracle_academy_student_day.jpg',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	3713,	1,	'2018-09-27 12:11:21',	'2018-09-27 12:11:21',	'2026-11-24 18:54:13',	NULL),
(53,	'Akreditasi Program Studi D4 Teknik Informatika yang Pertama',	'akreditasi-program-studi-d4-teknik-informatika-yang-pertama',	'<p>Pada tanggal 9-11 Desember 2018 telah dilaksanakan <em>Assessment</em> Lapangan Akreditasi Progam Studi D4 Teknik Informatika yang dilaksanakan oleh asesor Ibu Dr. Yani Nurhadryani, MT dari Institut Pertanian Bogor (IPB) dan Bapak Ir. Irawan Thamrin, MT dari Politeknik Negeri Bandung.</p>\n<p><em>Assessment</em> Lapangan ini bertujuan untuk melakukan proses validasi apa yang telah tertulis dalam borang akreditasi. Tujuan dari akreditasi ini untuk meningkatkan standar penilaian kualitas program studi. Dengan adanya akreditasi ini diharapkan calon mahasiswa, mahasiswa dan alumni program studi D4 Teknik Informatika dapat memperoleh manfaat yang baik. Diantaranya ialah :</p>\n<ol>\n<li>Menjadi nilai tambah positif dan menarik calon mahasiswa</li>\n<li>Mempermudah alumni untuk mendapatkan pekerjaan yang sesuai dengan kompetensinya</li>\n</ol>\n<p>Pada kegiatan tersebut dilakukan validasi terhadap dokumen pendukung dan juga fasilitas atau sarana &amp; prasarana yang digunakan saat kegiatan perkuliahan dan praktikum di gedung Jurusan Teknologi Informasi.</p>\n<p>Dalam sambutannya Direktur Politeknik Negeri Jember, Dr. Ir. Nanang Dwi Wahyono, MM menyampaikan harapan dengan adanya <em>Assessment</em> Lapangan ini, Progam Studi D4 Teknik Informatika mendapatkan hasil nilai yang terbaik demi kemajuan bersama.</p>',	9,	'AKREDITASI_TIF_3.jpeg',	1,	0,	1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	1,	1,	6332,	1,	'2018-12-14 08:52:31',	'2018-12-14 08:52:31',	'2026-11-24 18:59:14',	NULL),
(54,	'Yudisium Ke-XVII Jurusan Teknologi Informasi, Yudisium yang Kedua di Tahun 2018',	'yudisium-ke-xvii-jurusan-teknologi-informasi-yudisium-yang-kedua-di-tahun-2018',	'<p>Puji syukur ke hadirat Tuhan YME, Yudisium ke XVII sukses diselenggarakan dengan lancar. Kemarin tepat tanggal 13 Desember 2018 Jam 7.30 pagi Yudisium ke XVI yang diikuti oleh 133 orang yudisi dengan rincian 64 yudisi Program Studi Manajemen Informatika dan 69 yudisi Program Studi Teknik Komputer.</p>\n<p>Pra-acara dimulai dengan pemutaran video foto kenangan para yudisi selama mereka menempuh lika liku kehidupan kampus. Para yudisi dengan fokus melihat satu persatu foto kenangan dengan berbagai ekspresi dan emosi masing-masing.</p>\n<p>Acara resmi dimulai dari masuknya barisan ketua jurusan, sekretaris jurusan, ketua program studi, dosen dan teknisi yang diiringi oleh lagu Bagimu Negeri. Demi khitmatnya acara pembacaan doa yang di bawakan oleh Bapak Novianto Hadi Raharjo A.Md. agar acara berjalan dengan lancar dan dilanjutkan dengan menyanyikan Lagu Indonesia Raya dan Mars Polije.</p>\n<p>Selanjutnya, Sekretaris Jurusan Prawidya Destarianto, S.Kom. MT membaca Surat Keputusan Yudisium tentang mahasiswa yang namanya tertera pada putusan tersebut telah dinyatakan lulus dari Politeknik Negeri Jember.</p>\n<p>Acara dilanjutkan dengan pelepasan secara simbolis para yudisi oleh masing-masing program studi dan ketua jurusan Teknologi Informasi dengan maju satu persatu untuk diberikan sertifikat kelulusan mereka. Untuk Program Studi Teknik Komputer diwakilkan oleh Sekretaris Jurusan Prawidya Destarianto, S.Kom, MT. dikarenakan Bapak Hariyono Rakhmad, S.Pd. M.Kom berhalangan hadir pada kegiatan Yudisium kali ini.</p>\n<p>Setelah pelepasan secara simbolis para yudisi atas kelulusannya, perwakilan yudisi mempersembahkan sebuah lagu khusus untuk dosen yang hadir kala itu, diantara yudisi juga memberikan bunga kepada dosen sebagai bukti rasa terima kasih atas segala ilmu yang telah diberikan selama ini.</p>\n<p>Sekretaris jurusan kembali maju menuju podium untuk menyampaikan surat keputusan tentang Yudisi yang menerima predikat terbaik dari masing-masing program studi yaitu <strong>Hartono Wijaya Fandilayono</strong> dengan IPK <strong>3,82</strong> dari Manajemen Informatika dan <strong>Muhammad Widha Mahdi</strong> dengan IPK <strong>3,73</strong> dari Teknik Komputer.</p>\n<p>Akhir acara, dilakukan sesi foto bersama dosen, teknisi dan para yudisi untuk memberikan kenangan dan dokumentasi dari kegiatan Yudisium ke XVII dan dilanjutkan Ramah Tamah.</p>\n<p>Acara ini sukses terselenggara atas arahan oleh ketua Panitia Hermawan Arif, ST, MT beliau menyampaikan banyak terima kasih atas segenap panitia dan segenap yang terlibat dalam acara tersebut, acara tidak akan terselenggara dengan lancar tanpa kekompakan panitia sekalian.</p>\n<p><strong>(Djuliar)</strong></p>\n<div class=\"row\">\n<div class=\"col-md-6\">\n<blockquote class=\"instagram-media\" style=\"background: #FFF; border: 0; border-radius: 3px; box-shadow: 0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width: 540px; min-width: 326px; padding: 0; width: calc(100% - 2px);\" data-instgrm-permalink=\"https://www.instagram.com/p/BrWl-VPgKI_/?utm_source=ig_embed&amp;utm_medium=loading\" data-instgrm-version=\"12\">\n<div style=\"padding: 16px;\">\n<div style=\"display: flex; flex-direction: row; align-items: center;\"> </div>\n<div style=\"padding: 19% 0;\"> </div>\n<div style=\"display: block; height: 50px; margin: 0 auto 12px; width: 50px;\"> </div>\n<div style=\"padding-top: 8px;\">\n<div style=\"color: #3897f0; font-family: Arial,sans-serif; font-size: 14px; font-style: normal; font-weight: 550; line-height: 18px;\">View this post on Instagram</div>\n</div>\n<p style=\"color: #c9c8cd; font-family: Arial,sans-serif; font-size: 14px; line-height: 17px; margin-bottom: 0; margin-top: 8px; overflow: hidden; padding: 8px 0 7px; text-align: center; text-overflow: ellipsis; white-space: nowrap