INSERT INTO `lab_kegiatan` (`id`, `name`, `description`, `date`, `image`, `lab_id`, `created_at`, `updated_at`) VALUES
(1,	'Pelatihan Fundamental Teknisi - Batch 2',	'<p>Dalam rangka meningkatkan skill atau kemampuan dalam bagian teknis laboratorium dan dalam memberikan pelayanan terbaik bagi mahasiswa, pada tanggal 3 - 4 September telah dilaksanakan <strong>Pelatihan Fundamental Teknisi Sesi 2</strong>, pelatihan ini telah dilaksanakan sebelumnya pada sesi 1 yang bisa anda baca lebih lanjur pada artikel berikut <a title=\"http://jti.polije.ac.id/artikel/76-pelatihan-fundamental-skill-teknisi-jurusan-teknologi-informasi\" href=\"http://jti.polije.ac.id/artikel/76-pelatihan-fundamental-skill-teknisi-jurusan-teknologi-informasi\" target=\"_blank\"><strong>Pelatihan Fundamental Skill Teknisi Jurusan Teknologi Informasi</strong></a>.</p>\r\n<p>Kegiatan ini adalah kerjasama antara Jurusan Teknologi Informasi dengan esolusindo.com dan PT Brilian Tekno Utama dengan founder Brislian Anggi Wijaya dan juga sebagai pemateri pada pelatihan ini. Mas Brislian ini juga merupakan salah satu alumni dari program studi Teknik Komputer yang telah membangun bisnis dalam dunia Jaringan dan IT. Kegiatan ini diikuti oleh semua teknisi di Jurusan TI baik Teknisi di Kampus Jember maupun teknisi Kampus Bondowoso, alumni dan sebagian mahasiswa. Kegiatan ini dilaksanakan di Laboratorium Arsitektur Jaringan dan Komputer Jurusan Teknologi Informasi Politeknik Negeri Jember.</p>\r\n<p>Kegiatan pada hari pertama yaitu pada tanggal 3 September 2020 yaitu Virtualisasi Server dengan Proxmox, dimana kegiatan ini bertujuan untuk mengajarkan bagaimana manajemen resource pada sebuah server. Kemudian pada hari kedua, Diajarkan untuk bisa <span class=\"\" title=\"Edited\">Splicing</span> Fiber Optik Kabel dengan Alat Splicing.</p>\r\n<p>Pada akhir kegiatan Ketua Jurusan Teknologi Informasi memberi apresiasi  kepada seluruh peserta dan berpesan pada sambutannya di penutupan \"Semoga pelatihan ini memberi tambahan ilmu dan bermanfaat dalam kegiatan praktikum yang dalam beberapa minggu akan dilaksanakan Praktikum Blok di Laboratorium di Jurusan TI.<br><br><strong>(djuliar)</strong></p>',	'2020-09-04',	'fundamental_teknisi_2.jpg',	1,	NULL,	NULL),
(2,	'Perkuliahan Tatap Muka ',	'Wokrshop dan praktikum yang dilakukan secara luring di laboraturium RPL',	'2021-10-14',	'ptm.jpg',	5,	NULL,	NULL),
(3,	'HSK ',	'Kegiatan yang dilakukan seminggu 2 kali dengan tujuan untuk mempersiapkan mahasiswa dan mahasiswi program studi MIF internasional dalam memahami bahasa mandarin untuk program Study Exchange',	'2021-07-02',	'hsk.jpg',	5,	NULL,	NULL),
(4,	'PKM',	'Kegiatan peserta PKM yang menggunakan Laboraturium RPL untuk kegiatan PKP2 (Penilaian Kemajuan Pelaksanaan PKM) ',	'2021-09-16',	'pkm.jpg',	5,	NULL,	NULL),
(5,	'SBMPN 2021',	'Seleksi ujian masuk politeknik negeri yang dilaksanakan di Laboraturium RPL. Pelaksanaan seleksi ini menggunakan Sistem Computer Assisted Test (CAT)',	'2021-06-13',	'sbmpn.jpg',	5,	NULL,	NULL),
(11,	'TIF EXHIBITION 2020',	'Pameran Software , Sistem Informasi dan Website. ',	'2020-02-04',	NULL,	2,	NULL,	NULL),
(12,	'PYTHON APPLICATION ON HARDWERE ',	'Workshop yg membahas cara menyusun aplikasi  spesifikasi hardwere komputer dengan python',	'2020-09-08',	NULL,	2,	NULL,	NULL),
(13,	'WORKSHOP BUZZER',	'Workshop yang membahas terbukanya peluang profesi  bagi masyarakat dalam menggunakan media sosial.',	'2021-02-17',	NULL,	2,	NULL,	NULL),
(14,	'PYHON FUNDAMENTAL ',	'Workshop yg membahas  suatu konsep atau pengetahuan mendasar sekaligus penting dalam bahasa pemrograman python yang meliputi prinsip dan kaidah-kaidah yang dijadikan suatu pedoman untuk mempelajari bahasa pemrograman python.',	'2020-08-10',	NULL,	2,	NULL,	NULL),
(15,	'Perkualahan Tatap Muka ',	'Workshop dan pratikum yg dilakukan sacara luring di Laboraturim KSI .',	'2021-09-27',	NULL,	2,	NULL,	NULL),
(16,	'Implementasi Penelitian Pemodelan Tanaman PAJALE',	'Implementasi penelitian PNBP riset terapan pemodelan tanaman PAJALE. Kegiatan ini merupakan uji coba penggunaan alat IOT untuk pengukuran suhu dan pH tanah di lahan tanaman jagung Politeknik Negeri Jember. Link video: https://www.youtube.com/watch?v=Y1zwEo_eAo8',	'2021-10-15',	'iotpajale.jpeg',	3,	NULL,	NULL),
(17,	'Perkuliahan Tatap Muka di Ruang Laboratorium RSI',	'Ruang Laboratorium Rekaya Sistem Informasi memfasilitasi kegiatan perkuliahan tatap muka untuk matakuliah praktik yang ada di Jurusan Teknologi Informasi. Mahasiswa dan dosen dapat berinteraksi dalam proses pembelajaran praktik dengan memanfaatkan peralatan komputer yang ada di laboratorium dan bahan yang ada di laboratorium sesuai dengan kebutuhan praktik',	'2021-09-28',	'praktikumlab.jpeg',	3,	NULL,	NULL),
(18,	'Praktikum Tatap Muka di Ruang Workshop RSI',	'Ruang Workshop Rekaya Sistem Informasi memfasilitasi kegiatan perkuliahan tatap muka untuk matakuliah praktik yang ada di Jurusan Teknologi Informasi. Mahasiswa dan dosen dapat berinteraksi dalam proses pembelajaran praktik dengan memanfaatkan peralatan komputer secara mandiri dan bahan yang ada di laboratorium sesuai dengan kebutuhan praktik',	'2021-09-28',	'praktikumworkshop.jpeg',	3,	NULL,	NULL),
(19,	'Pelatihan AI with Machine Learning in Java',	'Dalam rangka pengembangan kompetensi keilmuan bagi dosen dan teknisi setiap Garis di jurusan Teknologi Informasi melakukan banyak sekali pelatihan maupun kegiatan-kegiatan fundamental lainnya, salah satunya yang di sajikan oleh Garis 5 bidang Kecerdasan Buatan di Laboratorium Rekayasa Sistem Informasi (RSI) berkolaborasi dengan Oracle Academy dalam pengadaan Pelatihan AI with Machine Learning in Java. Kegiatan ini berlangsung selama 5 hari, pada tanggal 7 - 11 Juni 2021',	'2021-06-07',	'oracleAI.jpg',	3,	NULL,	NULL),
(20,	'Diskusi dan Sharing bersama Dosen Jurusan Teknik',	'Topik diskusi dan sharing tentang teknologi drone. Tujuannya adalah persiapan penelitian PNBP di lingkungan Politeknik Negeri Jember',	'2021-06-04',	'diskusidrone.jpeg',	3,	NULL,	NULL),
(21,	'Diskusi dan Sharing bersama PT.Mangli Djaya Raya',	'Topik diskusi dan sharing tentang update teknologi terkini yang digunakan di PT. Mangli Djaya Raya. Diskusi dan sharing ini bertujuan untuk kerjasama riset dan pengembangan bidang terapan. Kolaborasi ini digunakan untuk dapat berkompetisi pada program penelitian terapan yang diselenggarakan oleh Kemdikbud',	'2021-05-25',	'MDR.jpg',	3,	NULL,	NULL),
(22,	'Diskusi dan Sharing bersama PT. Data Global Inspirasi',	'Topik diskusi dan sharing tentang update teknologi terkini yang digunakan di PT. Data Global Inspirasi. Diskusi dan sharing ini bertujuan untuk kerjasama riset dan pengembangan bidang terapan. Kolaborasi ini digunakan untuk dapat berkompetisi pada program penelitian terapan yang diselenggarakan oleh Kemdikbud',	'2021-05-24',	'diskusidatains.jpeg',	3,	NULL,	NULL),
(23,	'Diskusi dan Sharing bersama Denpasar Institute',	'Topik diskusi dan sharing tentang penjajakan kerjasama riset dan pengembangan yang mengarah ke roadmap Garis Kecerdasan Buatan yang ada di Laboratorium Rekayasa Sistem Informasi, Link: https://www.denpasarinstitute.com/berita/read/79/denpasar-institute-jajaki-kerjasama-riset-pengembangan-sdm-dengan-garis-jurusan-teknologi-informasi-politeknik-negeri-jember.html',	'2021-04-28',	'denpasarinstitute.jpeg',	3,	NULL,	NULL),
(24,	'Pelatihan Dasar Data Sains',	'Dalam rangka pengembangan kompetensi keilmuan bagi dosen dan teknisi setiap Garis di jurusan Teknologi Informasi melakukan banyak sekali pelatihan maupun kegiatan-kegiatan fundamental lainnya, salah satunya yang di sajikan oleh Garis 5 bidang Kecerdasan Buatan di Laboratorium Rekayasa Sistem Informasi (RSI) berkolaborasi dengan PT. Global Data Inspirasi dalam pengadaan Pelatihan Dasar Data Sains. Kegiatan ini berlangsung selama 3 hari, pada tanggal 6-8 April 2021. Materi pelatihan: (1) Data Sains dan Data Collection, (2) Data Cleaning dan Transformation, dan (3) Clustering dan Classification. Link: http://jti.polije.ac.id/artikel/107-laporan-kegiatan-pelatihan-dasar-data-sains',	'2021-04-06',	'datains.jpg',	3,	NULL,	NULL);
INSERT INTO `lab_produk` (`id`, `name`, `description`, `category_id`, `link`, `team`, `lab_id`, `created_at`, `updated_at`) VALUES
(1,	'Sistem Informasi Tenaga Kesehatan Hewan (Dokternak',	'Sistem Informasi Tenaga Kesehatan Hewan (Dokternak) merupakan wadah penghubung antara user umum yaitu peternak / pet lovers dengan petugas kesehatan hewan yang ada di Bondowoso. User dapat melakukan konsultasi kepada petugas, melakukan pencarian petugas, mencari lokasi Puskeswan, dan lain sebagainya.',	1,	'https://www.dokternak.id/',	NULL,	5,	NULL,	NULL),
(2,	'New Protector',	'New protector aplikasi android yang dapat dijadikan sebagai media pembelajaran bagi penyandang disleksia.',	2,	'https://play.google.com/store/apps/details?id=gim.newprotector',	NULL,	5,	NULL,	'2023-08-20 03:11:01'),
(3,	'Keep Healthy',	'Keephealthy merupakan sebuah sistem informasi penyedia jasa layanan kebersihan dimana aplikasi ini menyediakan layanan – layanan service kebersihan yang siap untuk diperkerjakan sehingga bisa membantu orang-orang sibuk, yang tidak sempat membersihkan sendiri selain itu aplikasi ini membantu untuk membuka lapangan pekerjaan karena di dalam aplikasi keephealthy terdapat fitur daftar sebagai pegawai. Didalam aplikasi keephealthy terdapat fitur-fitur yang sangat mudah untuk digunakan bagi orang awam karena sistem yang telah dibuat sangat friendly',	1,	'https://wsjti.id/keephealthy/public/',	NULL,	5,	NULL,	'2023-08-20 03:11:46'),
(4,	'Booque (Aplikasi Berbagu Buku Bekas)',	'Booque adalah aplikasi mobile untuk berbagi buku bekas, aplikasi ini menghubungkan antara orang yang ingin menyumbangkan buku bekas, dan orang yang tertarik dengan buku tapi tidak dapat membelinya.',	1,	'https://wsjti.id/booque/public/',	NULL,	5,	NULL,	'2023-08-20 03:12:03'),
(5,	'SIMRS Teleconsultasi',	'Aplikasi hasil buah kerjasama mahasiswa politeknik negeri Jember dengan unit Rumah Sakit Jiwa Dr Radjiman Wediodiningrat Lawang, Malang. Aplikasi yang kita kembangkan yaitu sebuah aplikasi yang memudahkan pasien dalam konsultasi online yang diberi nama \" Telekonsultasi\". Dimana aplikasi ini berfungsi sebagai penghubung pasien dengan dokter secara daring. Dengan adanya apkikasi ini pasien cukup dirumah saja dapt melakukan konsultasi secara online. Fitur yang tersedia dalam aplikasi ini, yaitu pembayaran online, jadwal dokter, riwayat pasien, pendaftaran online dan juga konsultasi online. Aplikasi ini digunakan oleh pihak rumah sakit seperti dokter dan admin serta pasien.',	1,	'http://telekonsul.workshopjti.com/',	NULL,	5,	NULL,	'2023-08-20 03:12:12'),
(6,	'Bantu Gerak',	'Bantu Gerak merupakan Sistem Informasi berbasis Website sebagai wadah untuk melakukan donasi dan penggalangan dana secara Online. Sistem Informasi Bantugerak juga mengintegrasikan payment gateway yang lengkap menggunakan Midtrans untuk meningkatkan keamanan dan kepercayaan pengguna.',	1,	'http://bantugerak.my.id/',	NULL,	5,	NULL,	'2023-08-20 03:12:21'),
(7,	'Match Cat',	'Match Cat aplikasi android yang cocok untuk para pencinta kucing ras dalam Match Cat pemilik kucing dapat menentukan jodoh terbaik untuk kucingnya, dilengkapi dengan fitur - fitur yang mempermudah dating kucing',	2,	'https://play.google.com/store/apps/details?id=dita.shafira.mate',	NULL,	5,	NULL,	'2023-08-20 03:12:31'),
(8,	'Scrum App',	'Scrum App is All in One tools for managing your SCRUM projects. This app build to help scrum teams to develop product using SCRUM Framework. Control your backlogs, sprints, tasks board, documents, and many more.',	2,	'https://play.google.com/store/apps/details?id=com.nadahasnim.scrumapp',	NULL,	5,	NULL,	'2023-08-20 03:13:44'),
(9,	'Let’s Be A SIP Collage Student',	'Let\'s Be a SIP College Student merupakan Game Visual Novel edukasi yang menceritakan kehidupan seorang mahasiswa Manajemen Informatika di Politeknik Negeri Jember. Game ini dapat dimainkan di berbagai platform seperti android, desktop, dan web. Game dapat diunduh melalui link berikut : https://ama-soft.itch.io/lets-be-a-sip-college-student',	1,	'https://ama-soft.itch.io/lets-be-a-sip-college-student',	NULL,	5,	NULL,	'2023-08-20 03:13:55'),
(10,	'MLIJO',	'Aplikasi android sebagai media pemasaran bahan sandang dan pangan untuk mempermudah pelanggan dalam memesan dan mengetahui informasi berbagai jenis bahan sandang dan pangan yang dijual, diskusi, penjadwalan. Keuntungan yang diperoleh dengan menggunakan transaksi melalui aplikasi android adalah untuk meningkatkan pendapatan, omset pedagang dan data pemesanan dapat terdokumentasi digital yang diharapkan berguna bagi pedagang maupun pembeli.',	1,	'https://imnimda.web.id/mlijo/',	NULL,	5,	NULL,	'2023-08-20 03:14:09'),
(11,	'Packcless',	'Packclese sendiri melayani 4 layanan utama yaitu Laundry, Bersih-bersih ruangan, Paket barang, dan titip barang. Target pelanggan packclese yaitu mahasiswa dan masyarakat umum di sekitar jember terutama di sekitar kampus Unej, Polije dan Unmuh',	1,	'http://premium-care.workshopjti.com/',	NULL,	5,	NULL,	'2023-08-20 03:14:24'),
(12,	'Mencetak Pola Sketsa Dengan Proporsi yang Tepat',	'MySketch merupakan sebuah aplikasi yang bergerak pada bidang seni menggambar realis. MySketch dapat mencetak sebuah pola sketsa yang digunakan sebagai patokan untuk menyusun rancangan awal sketsa sehingga dapat mempermudah proses penyempurnaan gambar. Pola yang didapat menghasilkan sebuah bentuk dengan proporsi yang tepat untuk menciptakan sebuah gambaran yang memiliki tingkat kemiripan seperti objek aslinya. Pengguna dapat memanfaatkan fitur kamera saat menyusun rancangan sketsa untuk membuat gambar lebih sempurna melalui aplikasi MySketch.',	2,	'https://play.google.com/store/apps/details?id=com.project.MySketch',	NULL,	5,	NULL,	'2023-08-20 03:14:39'),
(13,	'Peta Sebaran COVID-19 Kabupaten Jember',	'Sistem Informasi Geografis Sebaran COVID-19 Kabupaten Jember',	1,	'https://covid19.polije.ac.id/',	NULL,	2,	NULL,	'2023-08-20 03:14:48'),
(18,	'Puzzle 3D Bentuk Virtual Reality',	'Permainan  Puzzle 3D Bentuk berbasis virtual reality merupakan permainan untuk  anak anak PAUD umur 4 – 6 tahun . Permainan ini dapat melatih motorik halus dan motorik kasar anak untuk memaksimalkan potensi pada diri anak sejak usia sedini mungkin. Selain itu, dapat melatih daya ingat dan kecerdasan anak. Permainan ini dapat menunjang aktifitas belajar anak dalam usia perkembangannya.',	3,	'https://youtu.be/kSUWQ1X-qX4',	'<ol><li>Aji Seto Arifianto\r\n</li><li>Egy Raka Tiony\r\n</li><li>Hisyam Haidar Amru\r\n</li><li>Achmad Syadidul Fahim (E41180100)\r\n</li><li>Nafis Hibatullah Lestamanta(E41180163)\r\n</li><li>Ratna Dwi Kristina Sari(E41180434)\r\n</li><li>Luqman Hakim(E41180965)</li></ol>',	6,	NULL,	'2023-08-30 22:22:29'),
(19,	'PERMAINAN PENGENALAN BUAH MENGGUNAKAN AUGMENTED REALITY (AR) BERBASIS ANDROID (FRUTERIA GAMES)',	'Aplikasi Permainan Pengenalan Buah (Fruteria Games) merupakan media pembelajaran yang dirancang dalam bentuk game khusus untuk anak usia 3-5 tahun. Hasil dari aplikasi ini berupa pengenalan buah-buahan dengan 2 bahasa menggunakan Augmented Reality berbasis Android, dengan tujuan untuk menambah pengetahuan anak dalam mengenal nama buah dalam bahasa Inggris, dan Indonesia. Aplikasi ini disajikan lebih menarik berupa gambar dan suara yang berfungsi untuk memudahkan anak mengenal bentuk buah dan juga cara pengucapannya dengan baik, dan marker yang apabila terdeteksi akan menampilkan buah dalam 3D pada layer smartphone untuk mempermudah anak dalam memVisualisasikan dan berinteraksi secara lebih nyata.',	4,	'https://youtu.be/0xJcd3FvAF8',	'1. Aji Seto Arifianto\r\n2. Azizah Wina Sriwinarsih (E41182254)\r\n3. Alvin(E41182112)\r\n5. Ana Farida(E41182196)',	6,	NULL,	'2023-08-20 03:16:13'),
(20,	'APLIKASI VR (VIRTUAL REALITY) UNTUK TERMINASI FIBER OPTIC',	'Virtual Reality Terminasi Fiber Optik dapat memberikan informasi mengenai proses terminasi fiber optic berbentuk 3D dan memberikan simulasi berupa teks, audio, dan animasi. Sehingga diharapkan hasil penelitian ini dapat membantu para siswa untuk mempelajari proses terminasi fiber optic secara virtual.\r\n\r\nKeunggulan :\r\n1. Mudah untuk digunakan\r\n2. Memudahkan dalam proses pembelajaran\r\n3. Mempersingkat waktu',	3,	'https://youtu.be/pMIJA2V_0rc',	'1. Aji Seto Arifianto\r\n2. Muhammad Rifqi Firmansyah (E41181149)\r\n3. Ferdiansyah R. Evanta (E41181181)\r\n4. Indah Qurrothul Uyun (E41181117) \r\n5. Kirana Yuwita E.Y (E41180960)',	6,	NULL,	'2023-08-20 03:17:07'),
(21,	'Modul Pembelajaran Organ Dalam Manusia Menggunakan Augmented Reality Berbasis Android',	'Edu-Sains adalah Modul Pembelajaran Organ Dalam Manusia Menggunakan Augmented Reality Berbasis Android.  yang berfungsi untuk mewujudkan suasana belajar dan proses pembelajaran agar peserta didik secara aktif mengembangkan potensi dirinya untuk memiliki kecerdasan ataupun keterampilan yang dibutuhkan. Dalam upaya meningkatkan mutu pendidikan,  sehingga dibuat materi organ dalam pada manusia yang dipelajari akan di visualisasikan dalam bentuk 3D.',	4,	'https://youtu.be/cMo8YdQK0ME',	'1. Aji Seto Arifianto\r\n2. Egy Raka Tiony\r\n3. Mochamad Ludfi Rahman (E41180507)\r\n4. Moch. Famri Noer Priambodo(E41180690)\r\n5. Franciska Wulandari(E41180738)\r\n6. Gabriela Caroline Runturambi(E41180617)',	6,	NULL,	'2023-08-20 03:17:19'),
(22,	'Pengembangan Latihan Luas Gerak Sendi Berbasis Mixed Reality Untuk Terapi Kekakuan Otot Pada Ekstremitas Atas',	'Inovasi perangkat latihan luas gerak sendi atau range of motion menggunakan Mixed Reality untuk terapi ektremitas atas pasca stroke.',	5,	'https://www.youtube.com/watch?v=Pc0Y_fH70Js',	'1. I Putu Dody Lesmana\r\n2. Al Busran',	6,	NULL,	'2023-08-20 03:17:31'),
(23,	'Virtual Data Center',	'layanan data center berbasis hypervisor di Jurusan Teknologi Informasi',	6,	'https://p-node.jti.polije.ac.id:8006',	NULL,	1,	NULL,	'2023-08-20 03:17:49'),
(24,	'Sistem Monitoring Suhu dan Pengairan Otomatis Pada Tumbuhan Stroberi Berbasis Website',	'Layanan monitoring suhu dan pengairan otomatis pada tanaman stroberi',	7,	'http://farizi.cloud.japutek.com',	NULL,	1,	NULL,	'2023-08-30 22:20:50'),
(25,	'Sistem Kendali Lampu Rumah Berbasis IoT Menggunakan Smartphone Android',	'Sistem Kendali Lampu Rumah Berbasis IoT Menggunakan Smartphone Android',	7,	'http://rika.link.arw.my.id/',	NULL,	1,	NULL,	'2023-08-20 03:18:17'),
(26,	'Alat Bantu Berjalan Untuk Penyandang Tunanetra Berbasis Mikrokontroler',	'Alat untuk memandu penyandang tunanetra',	8,	NULL,	NULL,	1,	NULL,	'2023-08-20 03:18:40'),
(27,	'SMART DOOR MENGGUNAKAN ESP32 CAM BERBASIS INTERNET of THINGS (IoT)',	'Pintu pintar berbasis esp32 cam',	7,	NULL,	NULL,	1,	NULL,	'2023-08-20 03:18:51'),
