(29,	'Sistem Buka Tutup Gerbang Menggunakan RFID Berbasis Internet of Things (IoT)',	'Sistem Buka Tutup Gerbang Menggunakan RFID Berbasis Internet of Things (IoT)',	7,	NULL,	NULL,	1,	NULL,	'2023-08-20 03:19:23'),
(30,	'SISTEM KUNCI PINTU BERBASIS FACE RECOGNITION MENGGUNAKAN ESP32-CAM',	'SISTEM KUNCI PINTU BERBASIS FACE RECOGNITION MENGGUNAKAN ESP32-CAM',	8,	NULL,	NULL,	1,	NULL,	'2023-08-20 03:20:20'),
(31,	'Sistem Monitoring Pencahayaan Pada Budidaya Buah Naga Merah Menggunakan Panel Surya Berbasis Arduino UNO',	'Sistem Monitoring Pencahayaan Pada Budidaya Buah Naga Merah Menggunakan Panel Surya Berbasis Arduino UNO',	7,	NULL,	NULL,	1,	NULL,	'2023-08-20 03:20:38'),
(32,	'Sistem Blocking Situs Berbahaya menggunakan Pi-hole Berbasis Docker Container',	'Sistem Blocking Situs Berbahaya menggunakan Pi-hole Berbasis Docker Container',	6,	NULL,	NULL,	1,	NULL,	'2023-08-20 03:21:08'),
(33,	'Aplikasi Pertempuran Surabaya 10 November Berbasis Scrum',	'untuk membuat Game \"Pertempuran Surabaya\" yang bisa digunakan sebagai media pembelajaran Sejarah Pertempuran Surabaya 10 November 1945 yang dikemas dalam sebuah game agar dapat menaikkan minat anak anak untuk mempelajari sejarah.',	9,	'https://www.youtube.com/watch?v=eAO5HrnPjyg',	'<ol><li>I Putu Dody Lesmana</li><li>Evan Hendra Lukito (E31171313)\r\n</li><li>M. Rizki Fadhoni (E31170087)\r\n</li><li>Hasan Saiful Rizal (E31170109)\r\n</li><li>Angga Andika Putra (E31170152)</li></ol>',	6,	NULL,	'2023-08-20 03:28:59'),
(34,	'Sistem pemodelan potensi tanaman pangan dengan pendekatan GIS dan DSS berbasis website',	'Salah satu penelitian yang dilakukan oleh Garis Kecerdasan Buatan. Penelitian ini dilakukan karena program ketahanan pangan nasional melalui upaya khusus pada komoditi unggulan yaitu Padi, Jagung dan Kedelai yang sudah dilakukan sejak tahun 2015 masih belum mendapatkan hasil yang maksimal. Permasalahan ini dipengaruhi oleh banyak faktor. Konsep Smart Village yang dirancang dalam penelitian ini bertujuan untuk menemukan pemodelan potensi tanaman pangan prioritas yang tepat untuk meningkat hasil produksi. Sistem pemodelan produksi tanaman ini menggunakan pendekatan teknologi  GIS dan DSS untuk penerapan sistem pertanian modern.',	10,	'https://www.smart-agrotech.com/',	NULL,	3,	NULL,	'2023-08-20 03:21:44'),
(35,	'Virtual Laboratorium Management System',	'Virtual laboratorium management system merupakan aplikasi berbasis website untuk peningkatan layanan laboratorium secara online. Fitur pada LMS ini terdiri dari: keanggotaan laboratorium, peminjaman alat, peminjaman ruang laboratorium, kegiatan laboratorium, e-library karya  laboratorium, dan pameran produk/aplikasi yang dikembangkan di laboratorium bersama dengan Garis Kecerdasan Buatan',	10,	'https://vlms-jti.anggagumilang.com/',	NULL,	3,	NULL,	'2023-08-20 03:26:03'),
(36,	'Self Assesment Covid-19',	'Aplikasi deteksi dini Covid-19 berbasis website yang digunakan untuk pegawai Politeknik Negeri Jember. Aplikasi ini dikembangkan dalam rangka partisipasi perguruan tinggi sebagai lembaga akademis yang melakukan penelitian untuk ikut serta dalam penyelesaian kasus pandemi Covid-19',	10,	'https://covid19.polije.ac.id/test/',	NULL,	3,	NULL,	'2023-08-20 03:26:14'),
(37,	'Workshop Daring JTI',	'Aplikasi Learning Management System untuk matakuliah workshop di lingkungan Jurusan Teknologi Informasi. Aplikasi ini dikembangkan sesuai karakteristik kebutuhan pembelajaran workshop',	10,	'https://elearning.wslab-jti.com/',	NULL,	3,	NULL,	'2023-08-20 03:26:26');
INSERT INTO `laboratorium` (`id`, `name`, `alias`, `description`, `chairman`, `image`, `phone`, `email`, `website`, `address`, `additional`, `active`, `created_at`, `updated_at`) VALUES
(1,	'Arsitektur dan Jaringan Komputer',	'AJK',	'<p>Lab Arsitektur dan Jaringan Komputer adalah merupakan laboratorium yang berada dibawah Jurusan Teknologi Informasi di Politeknik Negeri Jember, yang menyediakan fasilitas lengkap untuk penelitian, pelatihan dan kegiatan praktikum untuk mahasiswa khusus untuk bidang arsitektur dan jaringan komputer.</p>\r\n<h4>Mata Kuliah</h4>\r\n<ol>\r\n<li>Jaringan Komputer</li>\r\n<li>Administrasi Sistem</li>\r\n<li>Jaringan Komputer II</li>\r\n<li>Jaringan Komputer III</li>\r\n<li>Jaringan Nirkabel</li>\r\n<li>Keamanan Jaringan</li>\r\n<li>Jaringan Komputer IV</li>\r\n<li>Administrasi Jaringan Komputer</li>\r\n<li>Proyek Jaringan Komputer</li>\r\n<li>Proyek Sistem Informasi</li>\r\n</ol>',	5,	'ajk_6892f48e63e75.jpg',	NULL,	'labajk@polije.ac.id',	'http://jti.polije.ac.id/lab/ajk',	'Gedung Jurusan Teknologi Informasi Lt. 2 No. F2.15 Jl. Mastrip PO.BOX 164 Jember Jember Jawa Timur 68101 Indonesia',	'[]',	1,	'2023-08-18 03:01:13',	'2026-07-14 12:45:49'),
(2,	'Komputasi dan Sistem Informasi',	'KSI',	'<p class=\"text-justify\">Laboratoium Komputasi dan Sistem Informasi merupakan fasilitas bagi mahasiswa dan dosen dalam kegiatan praktikum dan penelitian dibidang Sistem Informasi dan Database. Laboratoium Komputasi dan Sistem Informasi yang lebih dikenal dengan nama Lab KSI dibawah kelola Jurusan Teknologi Informasi, Politeknik Negeri Jember.</p>\r\n<p class=\"text-justify\">Saat ini laboratoium ini melayani praktikum mahasiswa untuk program studi Teknik Komputer, Manajemen Informatika dan Teknik Informatika. Terdapat 35 komputer untuk kegiatan praktikum dan penelitian untuk mahasiswa dan dosen. Selain itu beberapa pelatihan terkait bidang keilmuan sistem informasi dan database atas permintaan/kebutuhan masyarakat/industri dapat dilakukan di laboratorium ini.</p>\r\n<h4>Mata Kuliah</h4>\r\n<ol>\r\n<li>Pemrograman Terstruktur</li>\r\n<li>Algoritma Pemrograman</li>\r\n<li>Logika Informatika</li>\r\n<li>Struktur Data</li>\r\n<li>Pemrograman Berbasis Objek</li>\r\n<li>Basis Data Relasional</li>\r\n<li>Sistem Basis Data</li>\r\n<li>Sistem Basis Data Terdistribusi</li>\r\n<li>Manajemen Basis Data</li>\r\n<li>Pemrograman Visual</li>\r\n</ol>',	30,	'ksi_6893004fa76fd.jpg',	NULL,	'labksi@polije.ac.id',	'http://jti.polije.ac.id/lab/ksi',	'Gedung Jurusan Teknologi Informasi Lt. 2 No. F2.12 Jl. Mastrip PO.BOX 164 Jember Jember Jawa Timur 68101 Indonesia',	'[{\"teknisi\":\"17\"}]',	1,	'2023-08-18 03:02:20',	'2026-02-23 11:36:56'),
(3,	'Rekayasa Sistem Informasi',	'RSI',	'<p>Laboratorium Rekayasa Sistem Informasi merupakan laboratorium yang diperuntukan untuk menunjang kegiatan civitas akademika dalam penyelengaraan praktikum, pelatihan, dan penyelesaian tugas mata kuliah di bidang Rekayasa dan system informasi. Serta mengembangkan ilmu berbasis Rekayasa Sistem Informasi. Dalam hal ini untuk mengembangkan mahasiswa harus memiliki etika profesi dan sikap professional.</p>\r\n<p>Laboratorium ini digunakan untuk kegiatan praktikum Mahasiswa Jurusan Teknologi Informasi baik dari program studi Manajemen Informatika (D3), Teknik Komputer (D3), dan Teknik Informatika (D4). Secara khusus Lab RSI diperuntukan untuk menunjang kegiatan di bidang pemrograman sistem informasi dan kecerdasan buatan. Kapasitas Lab RSI sebanyak 30 komputer untuk mahasiswa dan 1 komputer untuk dosen.</p>\r\n<p>Matakuliah:</p>\r\n<ol>\r\n<li>Workshop Basis Data</li>\r\n<li>Workshop Sistem Informasi Berbasis Desktop</li>\r\n<li>Workshop Berbasis Web</li>\r\n<li>Workshop Aplikasi Mobile</li>\r\n<li>Analisis dan Desain Sistem Informasi</li>\r\n<li>Sistem Pertanian Digital</li>\r\n<li>Pemrograman Dasar</li>\r\n</ol>',	25,	'rsi_689300218d830.jpg',	NULL,	'labrsi@polije.ac.id',	'http://jti.polije.ac.id/lab/rsi',	'Gedung Jurusan Teknologi Informasi Lt. 2 No. F2.5 Jl. Mastrip PO.BOX 164 Jember Jember Jawa Timur 68101 Indonesia',	'[{\"teknisi\":\"20\"}]',	1,	'2023-08-18 03:42:32',	'2025-08-06 14:11:29'),
(4,	'Sistem Komputer dan Kontrol',	'SKK',	'<p class=\"text-justify\">Laboratorium Sistem Komputer dan Kontrol berdiri sejak tahun 2007 pada awalnya adalah sebagai fasislitas untuk ketersediaan bagi mahasiswa teknik komputer dalam melakukan kegiatan praktikum dan penelitian dibidang kontrol dan robotika. Laboratorium Sistem Komputer dan Kontrol yang lebih dikenal oleh mahasiswa Politeknik Negeri Jember dengan nama Lab SKK adalah salah satu laboratorium dibawah kelola di Jurusan Teknologi Informasi, Politeknik Negeri Jember.</p>\r\n<p class=\"text-justify\">Saat ini laboratoium ini melayani praktikum mahasiswa untuk program studi Teknik Komputer, Manajemen Informatika dan Teknik Informatika. Laboratorium Sistem Komputer dan Kontrol juga sebagai fasilitas untuk melakukan kegiatan penelitian baik bagi dosen maupun mahasiswa. selain itu beberapa pelatihan singkat terkait bidang keilmuan sistem komputer maupun sistem kontrol atas permintaan/kebutuhan masyarakat/industri dapat dilakukan di laboratorium ini.</p>\r\n<h4>Mata Kuliah</h4>\r\n<ol>\r\n<li>Elektronika Dasar</li>\r\n<li>Rangkaian Digital</li>\r\n<li>Perancangan Elektronika</li>\r\n<li>Instrumentasi</li>\r\n<li>Pemrograman</li>\r\n<li>Antarmuka</li>\r\n<li>Mikrokontroler</li>\r\n</ol>',	18,	'skk_64df4b8ec9f23.jpg',	NULL,	'labskk@polije.ac.id',	'http://jti.polije.ac.id/lab/skk',	'Gedung Jurusan Teknologi Informasi Lt. 2 No. F2.1 Jl. Mastrip PO.BOX 164 Jember Jember Jawa Timur 68101 Indonesia',	'[{\"teknisi\":\"19\"}]',	1,	'2023-08-18 03:44:30',	'2023-08-30 21:16:17'),
(5,	'Rekayasa Perangkat Lunak',	'RPL',	'<p class=\"text-justify\">Laboratorium Rekayasa Perangkat Lunak yang kemudian lebih populer disebut sebagai Lab RPL resmi beroperasi sejak Agustus 2015. Lab RPL pernah digunakan untuk pelatihan Database (DB Design dan Programming) Serta Java (Fundamental dan Programming) yang merupakan kerjasama Jurusan Teknologi Informasi Politeknik Negeri Jember dan Oracle Academy Indonesia, pelatihan tersebut diikuti 42 peserta yang terdiri dari dosen-dosen beberapa perguruan tinggi di wilayah Jawa Timur.</p>',	43,	'rpl_6892f8f81fa80.jpg',	NULL,	'labrpl@polije.ac.id',	'http://jti.polije.ac.id/lab/rpl',	'Gedung Jurusan Teknologi Informasi Lt. 2 No. F2.11 Jl. Mastrip PO.BOX 164 Jember Jember Jawa Timur 68101 Indonesia',	'[]',	1,	'2023-08-18 03:45:46',	'2026-07-14 12:48:43'),
(6,	'Multimedia Cerdas',	'MMC',	'<p>Laboratorium Multimedia Cerdas yang kemudian lebih populer disebut sebagai Lab MMC resmi beroperasi sejak Februari 2020 berdasarkan <strong>SK Direktur Politeknik Negeri Jember Nomor 17407/PL17/KP/SK/2019 </strong>Tanggal 27 Desember 2019.</p>\r\n<p>Laboratorium ini digunakan untuk kegiatan praktikum Mahasiswa Jurusan Teknologi Informasi baik dari program studi Manajemen Informatika (D3), Teknik Komputer (D3), dan Teknik Informatika (D4).</p>\r\n<p>Secara khusus Lab MMC diperuntukan menunjang kegiatan di bidang Multimedia. Lab MMC dilengkapi dengan berbagai perangkat penunjang Interactive Media Design, Augmented &amp; Virtual Reality, dan Teknologi Game</p>\r\n<h4>Mata Kuliah</h4>\r\n<ol>\r\n<li>Pengolahan Citra Digital</li>\r\n<li>Computer Vision</li>\r\n<li>Antarmuka</li>\r\n<li>Workshop Sistem Cerdas</li>\r\n<li>Interaksi Manusia dan Komputer</li>\r\n<li>Aplikasi Mobile</li>\r\n</ol>\r\n<div class=\"text-center\">\r\n<iframe src=\"https://www.youtube.com/embed/J8DkkEqOpPA\" title=\"YouTube video player\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"\" width=\"560\" height=\"315\" frameborder=\"0\"></iframe></div>',	19,	'mmc_64df4c2bb89b3.jpg',	NULL,	'labmmc@polije.ac.id',	'http://jti.polije.ac.id/lab/mmc',	'Gedung Jurusan Teknologi Informasi Lt. 2 No. F2.10 Jl. Mastrip PO.BOX 164 Jember Jember Jawa Timur 68101 Indonesia',	'[{\"teknisi\":\"18\"}]',	1,	'2023-08-18 03:47:07',	'2023-08-30 21:17:24'),
(8,	'Laboratorium Polije - Nganjuk',	'KSI-MMC-NGK',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'Jl. Gatot Subroto No 02, Nganjuk - Jawa Timur',	'[{\"teknisi\":\"\"}]',	1,	'2023-08-18 03:49:46',	'2025-10-15 12:59:06'),
(9,	'Laboratorium Polije - Sidoarjo',	'RSI-SKK-SDJ',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'Jl. Kutuk Barat gg. Sekolahan No 1 Sidokare, Sidoarjo - Jawa Timur',	'[{\"teknisi\":\"\"}]',	1,	'2023-08-18 03:50:08',	'2023-08-30 21:18:21'),
(11,	'Laboratorium Polije - Sabu Raijua',	'MMC-SR',	'<p><br></p>',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[{\"teknisi\":\"\"}]',	1,	'2025-10-15 12:59:27',	'2025-10-15 13:41:19');
