INSERT INTO `page_galeries` (`id`, `title`, `slug`, `description`, `galeries`, `active`, `created_at`, `updated_at`) VALUES
(1,	'Ruang Administrasi',	'ruang-administrasi',	'<p>Ruang Administrasi atau lebih dikenal Area Perkantoran merupakan suatu area atau ruangan yang digunakan untuk melaksanakan berbagai tugas administratif dan manajerial di Jurusan Teknologi Informasi. Ruang administrasi biasanya merupakan pusat operasi untuk mengelola berbagai aspek kegiatan Jurusan dan Program Studi, termasuk perencanaan, pengorganisasian, pelaporan, pengawasan, dan dokumentasi.<br></p>',	'[{\"galery\":\"2\"},{\"galery\":\"3\"}]',	1,	'2023-09-27 12:16:12',	'2023-09-27 16:12:24'),
(2,	'Ruang Dosen',	'ruang-dosen',	'<p>Ruang dosen berfungsi sebagai ruang kerja para dosen. Ruang ini dilengkapi dengan meja kerja dan kursi yang biasanya dimanfaatkan oleh dosen &amp; mahasiswa untuk sara diskusi/konsultasi. Ruang dosen juga dilengkapii dengan almari untuk tempat menyimpan buku dan dokumen, serta pendingin ruang (AC).<br></p>',	'[{\"galery\":\"4\"}]',	1,	'2023-09-27 14:32:32',	'2023-09-27 14:32:32'),
(3,	'Fasilitas JTI di PSDKU Nganjuk',	'psdku-nganjuk',	'<iframe src=\"https://www.youtube.com/embed/z3fCDVNboIQ?si=G8xZOVZ_YeWgGWk1\" title=\"YouTube video player\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen=\"\" width=\"100%\" height=\"630\" frameborder=\"0\"></iframe>',	'[{\"galery\":\"5\"},{\"galery\":\"6\"},{\"galery\":\"7\"}]',	1,	'2023-09-27 16:29:49',	'2023-09-27 16:53:57'),
(4,	'Ruang Kelas Lantai 3',	'ruang-kelas',	'<p>Ruang Kelas di Jurusan Teknologi Informasi berada di Lantai 3, terdiri dari 12 kelas yang terbagi menjadi 2 kelas besar untuk perkuliahan dan 10 kelas mobile untuk praktikum mahasiswa, fasilitas dilengkapi dengan LCD Proyektor di setiap kelas, papan tulis, kursi dan meja kuliah. Fasilitas Toilet berada di setiap ujung dari lorong di Lantai 3.<br></p>',	'[{\"galery\":\"8\"}]',	1,	'2023-09-27 17:24:26',	'2023-09-27 17:25:50'),
(5,	'kampus-bondowoso',	'kampus-bondowoso',	NULL,	'[{\"galery\":\"9\"}]',	1,	'2024-06-07 10:08:28',	'2024-06-07 10:08:28'),
(6,	'Fasilitas JTI di PSDKU Sidoarjo',	'psdku-sidoarjo',	'<p style=\"text-align: center;\"><iframe frameborder=\"0\" src=\"//www.youtube.com/embed/sJtoUoUHnSY\" width=\"100%\" height=\"640\" class=\"note-video-clip\"></iframe><br></p>',	'[{\"galery\":\"10\"},{\"galery\":\"16\"},{\"galery\":\"15\"},{\"galery\":\"18\"},{\"galery\":\"17\"},{\"galery\":\"14\"},{\"galery\":\"13\"},{\"galery\":\"12\"},{\"galery\":\"11\"},{\"galery\":\"19\"}]',	1,	'2024-11-17 21:02:03',	'2024-11-17 23:30:07'),
(7,	'PSDKU Sabu Raijua',	'psdku-saburaijua',	NULL,	'[{\"galery\":\"20\"}]',	1,	'2025-09-02 11:03:07',	'2025-09-02 11:03:07');
INSERT INTO `pages` (`id`, `template`, `name`, `title`, `slug`, `content`, `image`, `extras`, `user_id`, `user_id_last_edit`, `active`, `meta_keyword`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1,	'about_us',	'Profil JTI',	'PROFIL JURUSAN TEKNOLOGI INFORMASI 2025-2029',	'profil-jti',	'<h5 style=\"text-align: left;\"><strong>Visi</strong></h5><p class=\"text-justify\">JTI menetapkan visi tahun 2025-2029 sebagai berikut :.</p>\r\n<p class=\"text-justify\">\"Menjadi Jurusan Teknologi Informasi yang berdaya saing dalam\r\nMengakselerasi Inovasi Digital di Bidang Agroteknotropika.\"</p>\r\n<h5 style=\"text-align: left;\"><strong>Misi</strong></h5>\r\n<p style=\"text-align: justify;\">Dalam rangka upaya mewujudkan Visi JTI, maka JTI menetapkan Misi yang terdiri dari :</p>\r\n<ol>\r\n	<li style=\"text-align: justify; \">Menyelenggarakan pendidikan vokasi berkualitas dan berdaya saing global.</li><li style=\"text-align: justify; \">Melaksanakan penelitian terapan dan inovasi teknologi berkelanjutan.</li><li style=\"text-align: justify; \">Mengoptimalkan kemitraan dengan industri, pemerintah, dan komunitas.</li><li style=\"text-align: justify; \">Menyelenggarakan tata kelola jurusan yang profesional dan berkelanjutan.</li></ol>\r\n<h5 style=\"text-align: left;\"><strong>Tujuan</strong></h5>\r\n<p style=\"text-align: justify; \">Tujuan Strategis JTI Polije tahun 2025-2029 terdiri dari :</p>\r\n<ol>\r\n	<li style=\"text-align: justify; \">Menghasilkan lulusan vokasi yang unggul, inovatif, dan\r\nberdaya saing di tingkat ASEAN dalam bidang Teknologi\r\nInformasi.</li><ul><li style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Lulusan dibekali dengan kompetensi teknis, soft skills,\r\netika profesional, serta semangat kewirausahaan berbasis\r\ndigital untuk mendukung transformasi dan kemandirian sektor\r\nagroteknotropika.</span></li></ul><li style=\"text-align: justify; \">Menghasilkan penelitian terapan dan inovasi digital\r\nberkelanjutan yang memberikan manfaat bagi masyarakat dan pengembangan agroteknotropika.</li><ul><li style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Mendorong dosen dan mahasiswa menghasilkan karya riset dan\r\npengabdian berbasis teknologi informasi yang aplikatif,\r\nramah lingkungan, serta berorientasi pada solusi nyata.</span></li></ul><li style=\"text-align: justify; \">Menyelenggarakan sistem pendidikan dan kemitraan strategis\r\nyang adaptif terhadap perkembangan teknologi global.</li><ul><li style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Mengembangkan kurikulum inovatif berbasis Project-Based\r\nLearning, memperluas jejaring kerja sama dengan industri dan institusi pendidikan di dalam serta luar negeri, guna\r\nmemperkuat daya saing lulusan di tingkat ASEAN.</span></li></ul><li style=\"text-align: justify; \">Mewujudkan tata kelola jurusan yang profesional, efektif,\r\ntransparan, dan berbasis teknologi informasi.</li><ul><li style=\"text-align: justify;\"><span style=\"font-size: 1rem;\">Menerapkan sistem manajemen digital yang efisien untuk\r\nmenjamin mutu tridharma, meningkatkan produktivitas\r\nakademik, serta memperkuat reputasi Jurusan Teknologi\r\nInformasi sebagai jurusan unggul dan berkelanjutan.</span></li></ul></ol>\r\n<hr style=\"text-align: justify;\">\r\n<div class=\"alert alert-dark\" role=\"alert\" style=\"text-align: justify;\">\r\n	<a href=\"https://jti.polije.ac.id/uploads/documents/jti/RENSTRA_JTI_2020-2024.pdf\" target=\"_blank\"><b>Dokumen\r\n			Rencana Strategis JTI 2020-2024</b></a>\r\n</div>\r\n<div class=\"alert alert-dark\" role=\"alert\" style=\"text-align: justify;\">\r\n	<a href=\"https://jti.polije.ac.id/uploads/documents/jti/CAPAIAN_JTI_2020-2024.pdf\" target=\"_blank\"><b>Capaian\r\n			Rencana Strategis JTI 2020-2024</b></a></div><div class=\"alert alert-dark\" role=\"alert\" style=\"text-align: justify;\"><a href=\"https://jti.polije.ac.id/uploads/documents/jti/RENSTRA_JTI_2025-2029.pdf\" target=\"_blank\"><b>Dokumen Rencana Strategis JTI 2025-2029&nbsp;</b></a>\r\n</div>\r\n<hr style=\"text-align: justify;\">\r\n<h3 class=\"fw-bold text-center\" style=\"text-align: justify;\"><img src=\"https://jti.polije.ac.id/img/pages/Struktur%20Organisasi%20JTI%202025%20img%20%281%29.jpg?_t=1754456625\" style=\"font-size: 1rem; text-align: left; width: 100%;\"></h3>\r\n<p></p>',	'page_64f6efc15d8e6.jpg',	NULL,	1,	1,	1,	NULL,	NULL,	'2023-08-14 11:39:18',	'2025-11-25 10:35:29',	NULL),
(2,	'services',	'Kalender Akademik',	'Kalender Akademik',	'kalender-akademik',	'<p><p></p><p></p><p></p><p></p><center></center><p></p><p></p><div style=\"text-align: center;\"><a href=\"https://drive.google.com/file/d/10SYV7TRjpadFN72A32z9eQapNFUS5s3u/view\" target=\"_blank\"><a href=\"https://drive.google.com/file/d/10SYV7TRjpadFN72A32z9eQapNFUS5s3u/view\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255); font-size: 1rem;\">Download SK Kalender Akademik 2026/2027</a></a></div><center></center><p></p><p></p><p></p></p>',	'page_6923f73531ac3.jpg',	'{\"meta_title\":\"Kalender Akademik\",\"meta_description\":null,\"meta_keywords\":null}',	1,	1,	1,	NULL,	NULL,	'2023-08-14 11:44:30',	'2026-08-27 11:43:18',	NULL),
(3,	'services',	'Tata Tertib Mahasiswa',	'Tata Tertib Mahasiswa',	'tata-tertib-mahasiswa',	'<p><span style=\"text-decoration: underline;\"><strong>ETIKA BERKOMUNIKASI SECARA LANGSUNG YANG BAIK KEPADA DOSEN DAN STAF</strong></span></p>\r\n<div class=\"entry-content\">\r\n<ol>\r\n<li>Bertemu dengan dosen sebaiknya pada saat jam kerja dan di lingkungan kampus Politeknik Negeri Jember. Jika terpaksa dilakukan di luar waktu dan tempat tersebut harus ada perjanjian atau kesepakatan dengan dosen yang bersangkutan terlebih dahulu.</li>\r\n<li>Pastikan anda bertemu dosen pada kondisi yang tepat (tidak sedang makan, sholat, berbicara dengan dosen lain, atau aktifitas pribadi lainnya).</li>\r\n<li>Sebelum anda bertemu pastikan HP dalam kondisi “silent” atau “flight mode”, agar konsentrasi anda tidak terganggu ketika berdiskusi atau membicarakan hal penting lainnya.</li>\r\n<li>Ketuk ruangan apabila anda akan bertemu dengan dosen diruangannya dan selalu ucapkan salam. Bila mendapat sahutan atau ijin untuk memasuki ruangan, sampaikan, “Maaf, apakah saya boleh meminta waktu untuk berbicara dengan Bapak/Ibu (sebut nama)?”.</li>\r\n<li>Bila dosen bersedia ditemui dan dipersilahkan, segera posisikan diri berhadapan langsung dengan dosen ybs dan sampaikan kepentingan anda secara jelas dan urut.</li>\r\n<li>Jika sudah selesai keperluan dengan dosen, ucapkan terima kasih dan salam kepada dosen tersebut.</li>\r\n</ol>\r\n<p><span style=\"text-decoration: underline;\"><strong>ETIKA MENGIRIM PESAN YANG BAIK KEPADA DOSEN DAN STAF</strong></span></p>\r\n<ol>\r\n<li>Sebaiknya pengiriman pesan dilakukan pada hari dan jam kerja.</li>\r\n<li>Pesan harus menggunakan Bahasa Indonesia yang baik dan benar, bukan bahasa gaul (ALAY).</li>\r\n<li>Pesan diawali dengan sapaan. Bagi muslim ucapkan salam “Assalamu’alaikum” jangan disingkat. Bagi non muslim gunakan kata “Selamat pagi” atau lainnya.</li>\r\n<li>Pesan harus berisi identitas mahasiswa (Nama, Kelas, dan Program Studi). Dosen tidak selalu menyimpan nomor semua mahasiswa.</li>\r\n<li>Tuliskan keperluan dengan jelas, singkat, dan tidak bertele-tele. Misalnya (“Saya ingin bimbingan, kapankah Bapak/Ibu bisa saya temui?”)</li>\r\n<li>Ucapkan terima kasih untuk menunjukkan kerendahan hati anda dan tutup pesan dengan salam.</li>\r\n</ol>\r\n<p><span style=\"text-decoration: underline;\"><strong>ETIKA BERPAKAIAN YANG BAIK UNTUK MAHASISWA LAKI-LAKI</strong></span></p>\r\n<ol>\r\n<li>Memakai baju yang sopan, rapi, dan bersih.</li>\r\n<li>Gunakan kemeja atau kaos berkerah.</li>\r\n<li>Memakai celana panjang yang rapi dan formal, serta bukan celana panjang jeans yang robek-robek.</li>\r\n<li>Memakai sepatu (Bukan sandal, selop, atau sepatu sandal).</li>\r\n</ol>\r\n<p><span style=\"text-decoration: underline;\"><strong>ETIKA BERPAKAIAN YANG BAIK UNTUK MAHASISWA PEREMPUAN</strong></span></p>\r\n<ol>\r\n<li>Memakai baju yang :\r\n<ul>\r\n<li>sopan, rapi, dan bersih</li>\r\n<li>tidak ketat</li>\r\n<li>tidak terbuka</li>\r\n<li>tidak transparan</li>\r\n</ul>\r\n</li>\r\n<li>Gunakan kemeja atau kaos berkerah.</li>\r\n<li>Memakai celana panjang atau rok yang sopan, tidak transparan, dan bukan berbahan jeans yang robek-robek.</li>\r\n<li>Memakai sepatu (Bukan sandal, selop, atau sepatu sandal).</li>\r\n</ol>\r\n<p><span style=\"text-decoration: underline;\"><strong>ETIKA DI DALAM KELAS (proses perkuliahan)</strong></span></p>\r\n<ol>\r\n<li>Sebelum dosen masuk ke dalam kelas, pastikan whiteboard dalam kondisi bersih. Setelah perkuliahan berakhir pastikan whiteboard dalam keadaan bersih dan LCD Proyektor dalam kondisi OFF.</li>\r\n<li>Tidak menggunakan topi atau sejenisnya.</li>\r\n<li>Dilarang makan dan minum dalam kelas.</li>\r\n<li>Memakai baju seragam di hari Senin dan Selasa.</li>\r\n<li>Memakai baju bebas sesuai dengan aturan tata tertib di hari Rabu, Kamis, dan Jum’at.</li>\r\n<li>Saat perkuliahan hp atau perangkat komunikasi lainnya dalam kondisi dimatikan.</li>\r\n<li>Jaket atau baju hangat hanya digunakan ketika sakit/ kedinginan.</li>\r\n<li>Bicara dan bertingkah laku sopan pada saat perkuliahan.</li>\r\n<li>Tas diletakkan di bawah atau di samping meja.</li>\r\n<li>Selalu minta ijin dosen saat akan keluar kelas.</li>\r\n<li>Mempersilahkan dosen untuk keluar kelas terlebih dahulu saat perkuliahan berakhir.</li>\r\n<li>Tidak gaduh saat menungu dosen dan saat selesai perkuliahan</li></ol><ol>\r\n</ol>\r\n</div>',	'page_64f95b9229e45.jpg',	'{\"meta_title\":null,\"meta_description\":null,\"meta_keywords\":null}',	1,	1,	1,	NULL,	NULL,	'2023-08-19 22:52:46',	'2025-11-24 13:20:38',	NULL),
