INSERT INTO `prodi` (`id`, `name`, `alias`, `description`, `coordinator`, `admin`, `profil_lulusan`, `struktur_kurikulum`, `mata_kuliah`, `akreditasi`, `image`, `active`, `parent_id`, `lft`, `rgt`, `depth`, `additional_info`, `ppm_cpl`, `peta_kurikulum`, `created_at`, `updated_at`) VALUES
(1,	'Manajemen Informatika',	'MIF',	'<h3>Visi</h3>\r\n<p class=\"text-justify\">Menjadi Program Studi unggul yang mampu menunjang visi POLIJE untuk menghasilkan ahli madya bidang informatika yang berdaya saing di Asia pada tahun 2035</p>\r\n<h3>Misi</h3>\r\n<ol>\r\n<li><span style=\"font-size: 1rem;\">Menyelenggarakan pendidikan vokasi yang berkarakter dalam bidang informatika, yang menghasilkan lulusan yang berkualitas, kompeten, bermoral, dan berjiwa wirausaha.</span><br></li><li>Memperkuat kerjasama dengan stakeholder dalam menjaga keterkinian konten kurikulum serta riset yang sesuai dengan kebutuhan masyarakat.</li><li>Mensinergikan keahlian sistem informasi pada bidang pertanian serta bidang ilmu lainnya melalui kegiatan pengabdian kepada masyarakat</li><li>Mengembangkan kerjasama tingkat nasional maupun internasional</li>\r\n</ol>\r\n<h3>Tujuan</h3>\r\n<p class=\"text-justify\">Berdasarkan visi misi yang telah di tetapkan, maka PS MIF mengarahkan tujuan penyelenggaraan program studi dalam lima tahun ke depan sebagai berikut :</p>\r\n<ol>\r\n<li>Menghasilkan lulusan yang mampu menjadi:\r\n<ol type=\"a\">\r\n<li>Programmer yang memiliki kompetensi Frontend Developer, UI UX experience, backend Developer, Web Services, Mobile Developer Android, Software Development Framework</li>\r\n<li>Data Analyst.</li><li>Bussines Intelligent Developer.<br></li>\r\n<li>Wirausahawan Informatika yang memiliki kompetensi membuka peluang usaha khususnya dalam bidang teknologi Informasi</li>\r\n</ol>\r\n</li>\r\n<li>Menghasilkan riset / penelitian kolaboratif yang bermanfaat bagi masyarakat dan berkontribusi terhadap keterkinian konten kurikulum</li>\r\n<li>Terciptanya kegiatan pengabdian kepada masyarakat yang bersinergi dengan bidang ilmu lainnya (multi disiplin ilmu) untuk menjawab kebutuhan masyarakat.</li>\r\n<li>Terwujudnya jaringan kerjasama yang mendukung penguatan program studi dalam bidang Pendidikan pengajaran, penelitian dan pengabdian kepada masyarakat</li>\r\n</ol>\r\n<h3>Sasaran dan Strategi Pencapaian</h3>\r\n<p class=\"text-justify\">Untuk mencapai tujuan yang dicanangkan PS MIF merumuskan sasaran strategis yang spesifik dan terukur dengan indikator yang diupayakan untuk tercapai pada kurun waktu yang ditetapkan secara berkesinambungan dan mendukung sasaran strategis POLIJE. Rumusan sasaran strategis PS MIF adalah sebagai berikut:</p>\r\n<ol>\r\n<li>Meluasnya Akses dan Meningkatnya Mutu Pendidikan</li>\r\n<li>Meningkatnya Kuantitas dan Kualitas Penelitian dan Pengabdian kepada Masyarakat</li>\r\n<li>Meningkatnya Kualitas Penjaminan Mutu Kegiatan Tridharma</li>\r\n<li>Meningkatnya Kualitas Pengelolaan Pendidikan</li>\r\n<li>Meningkatnya Kualitas Proses dan Hasil Kegiatan Kemahasiswaan</li>\r\n<li>Meningkatnya Hasil dan Manfaat Kerjasama</li>\r\n<li>Berkembangnya Budaya Kewirausahaan</li>\r\n</ol>',	9,	2,	'Profil Lulusan MIF.pdf',	'Distribusi Matkul MIF 2021.pdf',	'Distribusi Matkul MIF 2021.pdf',	'SERTIFIKAT AKREDITASI MIF POLIJE 2020 - 2025.pdf',	'mif_icon.svg',	1,	NULL,	2,	3,	1,	0,	NULL,	NULL,	'2023-08-18 19:16:23',	'2026-08-22 15:19:19'),
(2,	'Teknik Komputer',	'TKK',	'<h3>Visi</h3>\r\n<p class=\"text-justify\">Menjadi pusat pendidikan dan pengembangan vokasi bidang komputer yang menghasilkan ahli madya berdaya saing di Asia Tenggara pada tahun 2035.</p>\r\n<h3>Misi</h3>\r\n<ol>\r\n<li>Meningkatkan kualitas sumber daya insani yang berpengetahuan, berkeahlian, dan berbudaya di bidang komputer.</li>\r\n<li>Meningkatkan sinergi keahlian bidang komputer dengan bidang keahlian lainnya.</li>\r\n<li>Meningkatkan kegiatan layanan bidang komputer yang bermanfaat bagi masyarakat.</li>\r\n<li>Meningkatkan kualitas dan produktivitas riset bidang komputer yang inovatif.</li>\r\n<li>Meningkatkan kualitas dan produktivitas teknologi terapan bidang komputer yang bernilai ekonomis.</li>\r\n<li>Membentuk jiwa kemandirian beretika akademik bidang komputer.</li>\r\n</ol>\r\n<h3>Tujuan</h3>\r\n<ol>\r\n<li>Menyelenggarakan pendidikan vokasi bidang komputer dengan menghasilkan lulusan yang :</li>\r\n<ol type=\"a\">\r\n<li>Mampu mengamati dan memecahkan masalah serta terampil menerapkan IPTEK untuk melaksanakan pekerjaan manajerial tingkat menengah (midle-level) dibidang Teknologi Informasi dan Komunikasi (TIK) khususnya dibidang Teknologi Jaringan komputer dan perangkat keras, elektronika terapan serta pengembangan sistem komputer dan perangkat lunak.</li>\r\n<li>Memiliki jiwa entrepreneur dan technopreneur yang mampu bersaing di area global</li>\r\n</ol>\r\n<li>Menyelenggarakan riset rekayasa dan terapan serta pengabdian masyarakat dan kerjasama bidang komputer sesuai dengan keunikan industri atau lembaga yang kompeten.</li>\r\n</ol>\r\n<h3>Sasaran</h3>\r\n<ol>\r\n<li>Tercetak lulusan ahli madya berkualitas yang mempunyai kemampuan vokasi dan pengembangan bidang komputer berdasarkan etika dan kebenaran ilmiah.</li>\r\n<li>Menjadi Program Studi yang tanggap terhadap perkembangan sains, teknologi dan aplikasi bidang komputer yang dicirikan oleh etika akademik dan daya inovasi yang tinggi.</li>\r\n<li>Menjadi Program Studi yang dapat membantu dan memandu perubahan di masyarakat melalui karya pengabdian yang berkualitas.</li>\r\n</ol>',	44,	4,	'Profil Lulusan Kurikulum 2021-TKK.pdf',	'Organisasi Mata Kuliah Kurikulum 2021-TKK.pdf',	'Mata Kuliah Kurikulum 2021-TKK.pdf',	'SERTIFIKAT AKREDITASI 2025_TKK.pdf',	'tkk_icon.svg',	1,	NULL,	4,	5,	1,	1,	'PPM CPL - Prodi TKK.pdf',	'Peta Kurikulum TKK.pdf',	'2023-08-18 19:16:23',	'2026-08-22 15:19:19'),
(3,	'Teknik Informatika',	'TIF',	'<h3>Visi</h3>\r\n<p class=\"text-justify\">Menjadi Program Studi unggulan dibidang Teknik Informatika yang menghasilkan Sarjana Terapan berdaya saing di Asia tahun 2035.</p>\r\n<h3>Misi</h3>\r\n<ol>\r\n<li>Menyelenggarakan pendidikan vokasi untuk menghasilkan lulusan yang kompeten dan inovatif sehingga mampu bersaing di tingkat nasional dan internasional.</li>\r\n<li>Menyelenggarakan pengembangan ilmu pengetahuan dan teknologi terapan di bidang Teknik Informatika untuk diimplementasikan dalam kegiatan pendidikan, penelitian dan pengabdian kepada masyarakat.</li>\r\n<li>Menjalin kerjasama dalam maupun luar negeri guna meningkatkan mutu pendidikan, penelitian dan pengabdian kepada masyarakat.</li>\r\n</ol>\r\n<h3>Tujuan</h3>\r\n<p class=\"text-justify\">Guna tercapainya visi misi program studi maka perlu menetapkan tujuan program studi yang didasari pada relevansi, atmosfir akademik, manajemen internal, keberlanjutan dan efisiensi yang akan menghasilkan lulusan yang :</p>\r\n<ol>\r\n<li>Mampu mengembangkan sistem informasi dan melakukan pengelolaan sumberdaya informasi dengan berbagai teknik dan metode.</li>\r\n<li>Mampu membuat perangkat lunak baik berbasis desktop, website, maupun mobile untuk diterapkan pada berbagai bidang keilmuan.</li>\r\n<li>Mampu melaksanakan tugas sebagai staf, penyelia, hingga menjalankan fungsi manajerial tingkat menengah dalam bidang informatika.</li>\r\n<li>Memiliki kemampuan berwirausaha yang kompetitif dalam bidang informatika maupun bidang lainnya.</li>\r\n</ol>\r\n<h3>Sasaran</h3>\r\n<p>Sasaran program studi Teknik Informatika adalah :</p>\r\n<ol>\r\n<li>Meluasnya akses dan meningkatkan mutu dan relevansi pendidikan sehingga dapat menghasilkan lulusan Program Studi Teknik Informatika yang berkarakter, berdaya saing, dan sesuai dengan kebutuhan masyarakat.</li>\r\n<li>Menghasilkan penelitian dan pengabdian pada masyarakat yang berkualitas, dan berdaya inovasi tinggi.</li>\r\n<li>Mewujudnya tata kelola program studi yang sesuai dengan Good Polytechnic Governance.</li>\r\n<li>Peningkatan hasil dan manfaat kerjasama dengan calon pengguna lulusan, dengan lembaga lain dan dengan kampus luar negeri.</li>\r\n<li>Meningkatkan kreatifitas dan prestasi mahasiswa pada kompetisi tingkat nasional maupun internasional.</li>\r\n<li>Meningkatkan kemampuan berwirausaha khususnya dibidang informatika.</li>\r\n</ol>',	31,	5,	'PROFIL_LULUSAN_TIF_2026.pdf',	'KURIKULUM_2026.pdf',	'MATAKULIAH_TIF_2021.pdf',	'SERTIFIKAT_LAMINFOKOM_TEKNIK_INFORMATIKA_2023-2028.pdf',	'tif_icon.svg',	1,	NULL,	6,	7,	1,	0,	NULL,	NULL,	'2023-08-18 19:16:23',	'2026-08-22 15:19:19'),
